const UNITS=[{"id":"u3","roman":"III","title":"Ecuaciones","subtitle":"Ecuaciones lineales, cuadráticas y sus aplicaciones","icon":"03","groups":[{"title":"Ecuaciones lineales","subtitle":"Igualdad, despeje, paréntesis, fracciones y fórmulas"},{"title":"Problemas con ecuaciones lineales","subtitle":"Traducir un enunciado y resolverlo"},{"title":"Ecuaciones cuadráticas","subtitle":"Incompletas, factorización, fórmula general y discriminante"},{"title":"Problemas con ecuaciones cuadráticas","subtitle":"Áreas, productos y movimiento"}],"hints":["Una ecuación es una igualdad con una incógnita. Aquí aprenderás a despejarla paso a paso.","Ahora usarás las ecuaciones lineales para resolver situaciones descritas con palabras.","Las ecuaciones cuadráticas usan lo que aprendiste de factorización en la Unidad 2.","Cierre de la unidad: plantea y resuelve problemas que llevan a ecuaciones cuadráticas."],"ready":true}];
const STATIONS=[{"id":"u3-s001","title":"Igualdad e incógnita","subtitle":"Qué significa resolver","group":0,"symbol":"✧","minutes":40,"concept":"Una ecuación es una igualdad en la que hay una cantidad desconocida, llamada incógnita, que suele representarse con una letra como $x$. Resolver la ecuación es encontrar el valor de la incógnita que hace verdadera la igualdad; ese valor es la solución.\n\nPuedes pensar la igualdad como una balanza en equilibrio: si haces la misma operación en ambos lados (sumar, restar, multiplicar o dividir por un número distinto de cero), la balanza se mantiene equilibrada y obtienes una ecuación equivalente, es decir, con la misma solución.","example":"Resolvemos $x + 5 = 12$. Para dejar sola a $x$, restamos 5 en ambos lados:\n$$x + 5 - 5 = 12 - 5 \\quad\\Rightarrow\\quad x = 7$$\nVerificamos reemplazando: $7 + 5 = 12$, así que $x = 7$ es la solución.","media":[],"practice":[{"type":"input","kind":"number","q":"¿Cuál es la solución de la ecuación $x + 5 = 12$? Escribe el valor de $x$.","answer":"7","why":"Al reemplazar la incógnita por el valor correcto se cumple la igualdad: $7 + 5 = 12$."},{"q":"¿Cuál de estas ecuaciones es equivalente a $x - 3 = 8$?","options":["$x = 11$","$x = 5$","$x = 24$"],"correct":0,"why":"Sumamos 3 a ambos lados de la igualdad: $x - 3 + 3 = 8 + 3$, de donde $x = 11$."},{"type":"input","kind":"number","q":"¿Cuál es la solución de la ecuación $x + 14 = 29$? Escribe el valor de $x$.","answer":"15","why":"Al reemplazar: $15 + 14 = 29$. Se cumple la igualdad."},{"type":"input","kind":"number","q":"¿Cuál es la solución de la ecuación $x - 3 = 14$? Escribe el valor de $x$.","answer":"17","why":"Al reemplazar: $17 - 3 = 14$. Se cumple la igualdad."},{"type":"input","kind":"number","q":"¿Cuál es la solución de la ecuación $4x = 20$? Escribe el valor de $x$.","answer":"5","why":"Al reemplazar: $4 \\cdot 5 = 20$. Se cumple la igualdad."},{"type":"input","kind":"number","q":"¿Cuál es la solución de la ecuación $\\dfrac{x}{3} = 12$? Escribe el valor de $x$.","answer":"36","why":"Al reemplazar: $\\frac{36}{3} = 12$. Se cumple la igualdad."},{"type":"input","kind":"number","q":"¿Cuál es la solución de la ecuación $3x + 8 = 14$? Escribe el valor de $x$.","answer":"2","why":"Al reemplazar: $3 \\cdot 2 + 8 = 14$. Se cumple la igualdad."},{"q":"¿Cuál de estas ecuaciones es equivalente a $x + 5 = 8$?","options":["$x = -3$","$x = 13$","$x = 40$","$x = 3$"],"correct":3,"why":"Restamos 5 a ambos lados: $x = 8 - 5 = 3$."},{"q":"¿Cuál de estas ecuaciones es equivalente a $x - 4 = 6$?","options":["$x = 10$","$x = 24$","$x = 2$","$x = -2$"],"correct":0,"why":"Sumamos 4 a ambos lados: $x = 6 + 4 = 10$."},{"q":"¿Cuál de estas ecuaciones es equivalente a $2x + 6 = 10$?","options":["$2x = 4$","$x = 4$","$8x = 10$","$2x = 16$"],"correct":0,"why":"Restamos 6 a ambos lados: $2x = 10 - 6 = 4$."},{"q":"¿Cuál de estas ecuaciones es equivalente a $6x = 60$?","options":["$x = 66$","$x = 360$","$x = 10$","$x = 54$"],"correct":2,"why":"Dividimos ambos lados por 6: $x = \\frac{60}{6} = 10$."},{"q":"Para despejar $x$ en la ecuación $x + 8 = 20$, ¿qué operación se debe aplicar a ambos lados?","options":["Dividir ambos lados por $8$","Multiplicar ambos lados por $8$","Sumar $8$ a ambos lados","Restar $8$ a ambos lados"],"correct":3,"why":"La suma se deshace restando."},{"q":"Para despejar $x$ en la ecuación $x - 8 = 13$, ¿qué operación se debe aplicar a ambos lados?","options":["Dividir ambos lados por $8$","Restar $8$ a ambos lados","Multiplicar ambos lados por $8$","Sumar $8$ a ambos lados"],"correct":3,"why":"La resta se deshace sumando."},{"q":"Para despejar $x$ en la ecuación $2x = 6$, ¿qué operación se debe aplicar a ambos lados?","options":["Dividir ambos lados por $2$","Sumar $2$ a ambos lados","Restar $2$ a ambos lados","Multiplicar ambos lados por $2$"],"correct":0,"why":"La multiplicación por 2 se deshace dividiendo por 2."},{"q":"Para despejar $x$ en la ecuación $\\dfrac{x}{4} = 7$, ¿qué operación se debe aplicar a ambos lados?","options":["Restar $4$ a ambos lados","Multiplicar ambos lados por $4$","Sumar $4$ a ambos lados","Dividir ambos lados por $4$"],"correct":1,"why":"La división por 4 se deshace multiplicando por 4."},{"type":"input","kind":"number","q":"Si $x = 8$, ¿cuánto vale la expresión $5x + 7$?","answer":"47","why":"Reemplazamos: $5 \\cdot 8 + 7 = 47$."},{"type":"input","kind":"number","q":"Si $x = 8$, ¿cuánto vale la expresión $6x - 5$?","answer":"43","why":"Reemplazamos: $6 \\cdot 8 - 5 = 43$."},{"q":"Al reemplazar $x = 5$ en la ecuación $4x + 2 = 23$, ¿qué ocurre?","options":["Se cumple la igualdad","El lado izquierdo vale $23$ y la igualdad se cumple","No se puede reemplazar un valor en una ecuación","No se cumple la igualdad, porque el lado izquierdo vale $22$ y no $23$"],"correct":3,"why":"El lado izquierdo es $4 \\cdot 5 + 2 = 22$, que es distinto de $23$."},{"q":"¿Cuál de las siguientes expresiones es una ecuación?","options":["$8x^2 + 7$","$8x + 7 = 31$","$8 + 7$","$8x + 7$"],"correct":1,"why":"Una ecuación es una igualdad que contiene una incógnita. Las demás expresiones no tienen el signo $=$."},{"q":"¿Cuál de estas ecuaciones NO tiene como solución a $x = 2$?","options":["$2x + 2 = 8$","$2x + 6 = 10$","$3x + 4 = 10$","$3x + 3 = 9$"],"correct":0,"why":"Al reemplazar $x = 2$, el lado izquierdo de esa ecuación vale $6$, no $8$."}],"check":{"type":"input","kind":"number","q":"Una muestra de agua se calienta $6\\,^\\circ\\mathrm{C}$ y queda a $25\\,^\\circ\\mathrm{C}$. La temperatura inicial $T$ (en $^\\circ\\mathrm{C}$) cumple la ecuación $T + 6 = 25$. ¿Cuál era la temperatura inicial? Escribe solo el número, en $^\\circ\\mathrm{C}$.","answer":"19","why":"Restamos 6 a ambos lados: $T = 25 - 6 = 19$."},"draw":5,"checks":[{"q":"Una muestra de agua se calienta $6\\,^\\circ\\mathrm{C}$ y queda a $34\\,^\\circ\\mathrm{C}$. La temperatura inicial $T$ cumple $T + 6 = 34$. ¿Cuál era la temperatura inicial?","options":["$34\\,^\\circ\\mathrm{C}$","$40\\,^\\circ\\mathrm{C}$","$6\\,^\\circ\\mathrm{C}$","$28\\,^\\circ\\mathrm{C}$"],"correct":3,"why":"Restamos 6 a ambos lados: $T + 6 = 34$ → $T = 34 - 6 = 28$."},{"type":"input","kind":"number","q":"En una probeta hay cierto volumen $V$ de agua. Se agregan $11\\,\\mathrm{mL}$ de ácido y el total es $41\\,\\mathrm{mL}$, es decir $V + 11 = 41$. ¿Cuál era el volumen inicial de agua? Escribe solo el número, en $\\mathrm{mL}$.","answer":"30","why":"Restamos 11 a ambos lados: $V + 11 = 41$ → $V = 41 - 11 = 30$."},{"q":"Sobre una balanza hay un vaso de masa $m$. Al agregar $9\\,\\mathrm{g}$ de sal, la balanza marca $47\\,\\mathrm{g}$, así que $m + 9 = 47$. ¿Cuál es la masa del vaso?","options":["$9\\,\\mathrm{g}$","$56\\,\\mathrm{g}$","$38\\,\\mathrm{g}$","$47\\,\\mathrm{g}$"],"correct":2,"why":"Restamos 9 a ambos lados: $m + 9 = 47$ → $m = 47 - 9 = 38$."},{"type":"input","kind":"number","q":"Una plántula crece $4\\,\\mathrm{cm}$ durante una semana y llega a medir $40\\,\\mathrm{cm}$. Su altura inicial $h$ cumple $h + 4 = 40$. ¿Cuánto medía al inicio? Escribe solo el número, en $\\mathrm{cm}$.","answer":"36","why":"Restamos 4 a ambos lados: $h + 4 = 40$ → $h = 40 - 4 = 36$."},{"q":"Un globo sonda sube $12\\,\\mathrm{m}$ y alcanza una altura de $29\\,\\mathrm{m}$. Su altura inicial $y$ cumple $y + 12 = 29$. ¿Cuál era su altura inicial?","options":["$41\\,\\mathrm{m}$","$17\\,\\mathrm{m}$","$12\\,\\mathrm{m}$","$29\\,\\mathrm{m}$"],"correct":1,"why":"Restamos 12 a ambos lados: $y + 12 = 29$ → $y = 29 - 12 = 17$."},{"type":"input","kind":"number","q":"Una solución se enfría $13\\,^\\circ\\mathrm{C}$ hasta quedar a $18\\,^\\circ\\mathrm{C}$. La temperatura inicial $T$ cumple $T - 13 = 18$. ¿Cuál era la temperatura inicial? Escribe solo el número, en $^\\circ\\mathrm{C}$.","answer":"31","why":"Sumamos 13 a ambos lados: $T - 13 = 18$ → $T = 18 + 13 = 31$."},{"q":"Al evaporarse $6\\,\\mathrm{mL}$ de una solución quedan $21\\,\\mathrm{mL}$. El volumen inicial $V$ cumple $V - 6 = 21$. ¿Cuál era el volumen inicial?","options":["$27\\,\\mathrm{mL}$","$15\\,\\mathrm{mL}$","$126\\,\\mathrm{mL}$","$6\\,\\mathrm{mL}$"],"correct":0,"why":"Sumamos 6 a ambos lados: $V - 6 = 21$ → $V = 21 + 6 = 27$."},{"type":"input","kind":"number","q":"En una reacción se consumen $15\\,\\mathrm{g}$ de un reactivo y quedan $14\\,\\mathrm{g}$. La masa inicial $m$ cumple $m - 15 = 14$. ¿Cuál era la masa inicial? Escribe solo el número, en $\\mathrm{g}$.","answer":"29","why":"Sumamos 15 a ambos lados: $m - 15 = 14$ → $m = 14 + 15 = 29$."},{"q":"Un buzo asciende $3\\,\\mathrm{m}$ y queda a $11\\,\\mathrm{m}$ de profundidad. Su profundidad inicial $p$ cumple $p - 3 = 11$. ¿A qué profundidad estaba?","options":["$3\\,\\mathrm{m}$","$8\\,\\mathrm{m}$","$14\\,\\mathrm{m}$","$33\\,\\mathrm{m}$"],"correct":2,"why":"Sumamos 3 a ambos lados: $p - 3 = 11$ → $p = 11 + 3 = 14$."},{"type":"input","kind":"number","q":"Una colonia de bacterias pierde $8$ miles de individuos y quedan $36$ miles. El tamaño inicial $n$ cumple $n - 8 = 36$. ¿Cuántos miles había al inicio?","answer":"44","why":"Sumamos 8 a ambos lados: $n - 8 = 36$ → $n = 36 + 8 = 44$."},{"q":"Un auto avanza a $6\\,\\mathrm{km/h}$ y recorre $60\\,\\mathrm{km}$. El tiempo $t$ cumple $6t = 60$. ¿Cuántas horas viajó?","options":["$10\\,\\mathrm{h}$","$360\\,\\mathrm{h}$","$54\\,\\mathrm{h}$","$66\\,\\mathrm{h}$"],"correct":0,"why":"Dividimos por 6: $t = \\frac{60}{6} = 10$."},{"type":"input","kind":"number","q":"Una bomba entrega $3\\,\\mathrm{mL}$ por minuto y llena un recipiente con $36\\,\\mathrm{mL}$. El tiempo $t$ cumple $3t = 36$. ¿Cuántos minutos tarda? Escribe solo el número, en $\\mathrm{min}$.","answer":"12","why":"Dividimos por 3: $t = \\frac{36}{3} = 12$."},{"q":"Cada pastilla contiene $7\\,\\mathrm{mg}$ de un compuesto y se necesitan $35\\,\\mathrm{mg}$ en total. El número de pastillas $n$ cumple $7n = 35$. ¿Cuántas pastillas se requieren?","options":["$28$","$42$","$245$","$5$"],"correct":3,"why":"Dividimos por 7: $n = \\frac{35}{7} = 5$."},{"type":"input","kind":"number","q":"Un material tiene densidad de $6\\,\\mathrm{g/cm^3}$ y una muestra tiene masa $60\\,\\mathrm{g}$. El volumen $V$ cumple $6V = 60$. ¿Cuál es el volumen en $\\mathrm{cm^3}$? Escribe solo el número, en $\\mathrm{cm^3}$.","answer":"10","why":"Dividimos por 6: $V = \\frac{60}{6} = 10$."},{"q":"Una muestra de volumen $V$ se reparte en $5$ tubos iguales de $16\\,\\mathrm{mL}$ cada uno, así que $\\dfrac{V}{5} = 16$. ¿Cuál era el volumen total?","options":["$11\\,\\mathrm{mL}$","$16\\,\\mathrm{mL}$","$80\\,\\mathrm{mL}$","$21\\,\\mathrm{mL}$"],"correct":2,"why":"Multiplicamos por 5: $V = 5 \\cdot 16 = 80$."},{"q":"Una masa $m$ se divide en $8$ porciones iguales de $11\\,\\mathrm{g}$ cada una, es decir $\\dfrac{m}{8} = 11$. ¿Cuál era la masa total?","options":["$19\\,\\mathrm{g}$","$11\\,\\mathrm{g}$","$88\\,\\mathrm{g}$","$3\\,\\mathrm{g}$"],"correct":2,"why":"Multiplicamos por 8: $m = 8 \\cdot 11 = 88$."},{"q":"Un tanque tiene $40\\,\\mathrm{L}$ de agua y se llena a $3\\,\\mathrm{L}$ por minuto. Llega a $70\\,\\mathrm{L}$ cuando $3t + 40 = 70$. ¿Cuántos minutos pasaron?","options":["$10\\,\\mathrm{min}$","$\\dfrac{110}{3}\\,\\mathrm{min}$","$11\\,\\mathrm{min}$","$30\\,\\mathrm{min}$"],"correct":0,"why":"Restamos 40: $3t = 30$; dividimos por 3: $t = 10$."},{"q":"Una planta mide $5\\,\\mathrm{cm}$ y crece $7\\,\\mathrm{cm}$ por día. Mide $110\\,\\mathrm{cm}$ cuando $7t + 5 = 110$. ¿Cuántos días han pasado?","options":["$16\\ \\text{días}$","$15\\ \\text{días}$","$\\dfrac{115}{7}\\ \\text{días}$","$105\\ \\text{días}$"],"correct":1,"why":"Restamos 5: $7t = 105$; dividimos por 7: $t = 15$."},{"q":"Un sensor registra $15\\,^\\circ\\mathrm{C}$ y la temperatura sube $3\\,^\\circ\\mathrm{C}$ por minuto. Llega a $33\\,^\\circ\\mathrm{C}$ cuando $3t + 15 = 33$. ¿Cuántos minutos transcurrieron?","options":["$7\\,\\mathrm{min}$","$18\\,\\mathrm{min}$","$6\\,\\mathrm{min}$","$16\\,\\mathrm{min}$"],"correct":2,"why":"Restamos 15: $3t = 18$; dividimos por 3: $t = 6$."}],"drawCheck":5,"unit":0},{"id":"u3-s002","title":"Ecuaciones lineales","subtitle":"Despejar paso a paso","group":0,"symbol":"✧","minutes":40,"concept":"Una ecuación lineal con una incógnita tiene la forma $ax + b = c$, donde $a$, $b$ y $c$ son números y $a \\neq 0$. Para resolverla se deshacen las operaciones en orden inverso: primero se eliminan las sumas y restas, y luego se divide por el número que multiplica a la incógnita.\n\nCuando la incógnita aparece a ambos lados, se juntan primero los términos con $x$ en un lado y los números en el otro.","example":"Resolvemos $5x - 2 = 3x + 8$.\n$$\\begin{aligned}5x - 2 &= 3x + 8\\\\ 5x - 3x &= 8 + 2\\\\ 2x &= 10\\\\ x &= 5\\end{aligned}$$\nVerificamos: $5\\cdot 5 - 2 = 23$ y $3\\cdot 5 + 8 = 23$.","media":[],"practice":[{"type":"input","kind":"number","q":"Resuelve la ecuación:\n$$3x + 4 = 19$$\n\nEscribe el valor de $x$.","answer":"5","why":"Primero restamos 4 y luego dividimos por 3: $3x = 15$, de donde $x = 5$."},{"q":"Resuelve la ecuación:\n$$5x - 2 = 3x + 8$$","options":["$x = 3$","$x = 5$","$x = 10$"],"correct":1,"why":"Juntamos los términos con $x$ a un lado y los números al otro: $5x - 3x = 8 + 2$, luego $2x = 10$ y $x = 5$."},{"type":"input","kind":"number","q":"Resuelve la ecuación:\n$$2x+4 = 8$$\n\nEscribe el valor de $x$.","answer":"2","why":"Pasamos $4$ al otro lado: $2x = 4$; luego dividimos por 2: $x = 2$."},{"q":"Resuelve la ecuación:\n$$7x-10 = 39$$","options":["$x=7$","$x=29$","$x=6$","$x=8$"],"correct":0,"why":"Pasamos $10$ al otro lado: $7x = 49$; luego dividimos por 7: $x = 7$."},{"type":"input","kind":"number","q":"Resuelve la ecuación:\n$$2x+12 = 28$$\n\nEscribe el valor de $x$.","answer":"8","why":"Pasamos $12$ al otro lado: $2x = 16$; luego dividimos por 2: $x = 8$."},{"q":"Resuelve la ecuación:\n$$2x-10 = -6$$","options":["$x=3$","$x=-16$","$x=1$","$x=2$"],"correct":3,"why":"Pasamos $10$ al otro lado: $2x = 4$; luego dividimos por 2: $x = 2$."},{"type":"input","kind":"number","q":"Resuelve la ecuación:\n$$3x+5 = 26$$\n\nEscribe el valor de $x$.","answer":"7","why":"Pasamos $5$ al otro lado: $3x = 21$; luego dividimos por 3: $x = 7$."},{"q":"Resuelve la ecuación:\n$$4x-3 = 2x+9$$","options":["$x=2$","$x=3$","$x=-6$","$x=6$"],"correct":3,"why":"Juntamos las $x$ a un lado: $4x - 2x = 9 - -3$, es decir $2x = 12$. Entonces $x = 6$."},{"type":"input","kind":"number","q":"Resuelve la ecuación:\n$$4x+5 = x+8$$\n\nEscribe el valor de $x$.","answer":"1","why":"Juntamos las $x$ a un lado: $4x - 1x = 8 - 5$, es decir $3x = 3$. Entonces $x = 1$."},{"q":"Resuelve la ecuación:\n$$8x-7 = 4x+9$$","options":["$x=4$","$x=\\dfrac{1}{2}$","$x=\\dfrac{4}{3}$","$x=-4$"],"correct":0,"why":"Juntamos las $x$ a un lado: $8x - 4x = 9 - -7$, es decir $4x = 16$. Entonces $x = 4$."},{"type":"input","kind":"number","q":"Resuelve la ecuación:\n$$5x+8 = x+32$$\n\nEscribe el valor de $x$.","answer":"6","why":"Juntamos las $x$ a un lado: $5x - 1x = 32 - 8$, es decir $4x = 24$. Entonces $x = 6$."},{"q":"Resuelve la ecuación:\n$$5x+7 = 3x+19$$","options":["$x=6$","$x=\\dfrac{3}{2}$","$x=13$","$x=-6$"],"correct":0,"why":"Juntamos las $x$ a un lado: $5x - 3x = 19 - 7$, es decir $2x = 12$. Entonces $x = 6$."},{"type":"input","kind":"number","q":"Resuelve la ecuación:\n$$2x+11 = 5$$\n\nEscribe el valor de $x$.","answer":"-3","why":"Pasamos $11$ al otro lado: $2x = -6$; luego dividimos por 2: $x = -3$."},{"q":"Resuelve la ecuación:\n$$6x-5 = -17$$","options":["$x=-1$","$x=-3$","$x=-2$","$x=-22$"],"correct":2,"why":"Pasamos $5$ al otro lado: $6x = -12$; luego dividimos por 6: $x = -2$."},{"type":"input","kind":"number","q":"Resuelve la ecuación:\n$$9x+4 = -77$$\n\nEscribe el valor de $x$.","answer":"-9","why":"Pasamos $4$ al otro lado: $9x = -81$; luego dividimos por 9: $x = -9$."},{"q":"Resuelve la ecuación:\n$$41 - 6x = 5$$","options":["$x=6$","$x=\\dfrac{23}{3}$","$x=-6$","$x=36$"],"correct":0,"why":"Restamos 41 a ambos lados: $-6x = -36$; dividimos por $-6$: $x = 6$."},{"q":"Resuelve la ecuación:\n$$28 - 5x = 3$$","options":["$x=\\dfrac{31}{5}$","$x=25$","$x=-5$","$x=5$"],"correct":3,"why":"Restamos 28 a ambos lados: $-5x = -25$; dividimos por $-5$: $x = 5$."},{"q":"Resuelve la ecuación:\n$$42 - 6x = 6$$","options":["$x=36$","$x=6$","$x=8$","$x=-6$"],"correct":1,"why":"Restamos 42 a ambos lados: $-6x = -36$; dividimos por $-6$: $x = 6$."},{"q":"Para resolver $4x + 4 = 12$, ¿cuál es un primer paso correcto?","options":["Restar $4$ a ambos lados","Dividir solo el lado derecho por $4$","Sumar $4$ a ambos lados"],"correct":0,"why":"Primero se aísla el término con $x$: restamos 4 a ambos lados y queda $4x = 8$."},{"q":"Para resolver $8x - 2 = 2x + 14$, ¿cuál es un primer paso correcto?","options":["Dividir ambos lados por $x$","Restar $2$ solo en el lado izquierdo","Restar $2x$ a ambos lados","Sumar $2x$ a ambos lados"],"correct":2,"why":"Para juntar los términos con $x$ en un lado, restamos 2x a ambos lados."}],"check":{"q":"Un resorte mide 12 cm y se alarga 2 cm por cada masa que se le cuelga. Con $n$ masas, su longitud total (en cm) es $12 + 2n$. ¿Cuántas masas se necesitan para que el resorte mida 20 cm?","options":["$n = 10$","$n = 16$","$n = 4$"],"correct":2,"why":"Planteamos $12 + 2n = 20$, luego $2n = 8$ y $n = 4$."},"draw":5,"checks":[{"type":"input","kind":"number","q":"Un ciclista parte a $32\\,\\mathrm{m}$ del inicio de una ruta y avanza a $6\\,\\mathrm{m/s}$. Su posición cumple $x = 32 + 6t$. ¿En cuántos segundos estará a $98\\,\\mathrm{m}$ del inicio? Escribe solo el número, en $\\mathrm{s}$.","answer":"11","why":"Restamos 32: $6t = 66$; luego $t = 11$."},{"q":"Un dron está a $39\\,\\mathrm{m}$ de altura y asciende $5\\,\\mathrm{m}$ cada segundo, de modo que $y = 39 + 5t$. ¿Cuántos segundos tarda en llegar a $79\\,\\mathrm{m}$?","options":["$9\\,\\mathrm{s}$","$\\dfrac{118}{5}\\,\\mathrm{s}$","$40\\,\\mathrm{s}$","$8\\,\\mathrm{s}$"],"correct":3,"why":"Restamos 39: $5t = 40$; luego $t = 8$."},{"type":"input","kind":"number","q":"Una planta mide $17\\,\\mathrm{cm}$ y crece $8\\,\\mathrm{cm}$ por día, así que $h = 17 + 8t$. ¿En cuántos días medirá $33\\,\\mathrm{cm}$? Escribe solo el número, en $\\text{días}$.","answer":"2","why":"Restamos 17: $8t = 16$; luego $t = 2$."},{"q":"La temperatura de una reacción es $21\\,^\\circ\\mathrm{C}$ y aumenta $5\\,^\\circ\\mathrm{C}$ cada minuto: $T = 21 + 5t$. ¿En cuántos minutos llegará a $41\\,^\\circ\\mathrm{C}$?","options":["$20\\,\\mathrm{min}$","$\\dfrac{62}{5}\\,\\mathrm{min}$","$5\\,\\mathrm{min}$","$4\\,\\mathrm{min}$"],"correct":3,"why":"Restamos 21: $5t = 20$; luego $t = 4$."},{"type":"input","kind":"number","q":"Un reactor ya produjo $29\\,\\mathrm{g}$ de un compuesto y produce $7\\,\\mathrm{g}$ por hora: $m = 29 + 7t$. ¿En cuántas horas habrá $78\\,\\mathrm{g}$? Escribe solo el número, en $\\mathrm{h}$.","answer":"7","why":"Restamos 29: $7t = 49$; luego $t = 7$."},{"q":"Un submarino está a $39\\,\\mathrm{m}$ de profundidad y desciende $3\\,\\mathrm{m}$ por minuto: $p = 39 + 3t$. ¿Cuántos minutos tarda en llegar a $57\\,\\mathrm{m}$?","options":["$32\\,\\mathrm{min}$","$6\\,\\mathrm{min}$","$7\\,\\mathrm{min}$","$18\\,\\mathrm{min}$"],"correct":1,"why":"Restamos 39: $3t = 18$; luego $t = 6$."},{"type":"input","kind":"number","q":"La relación entre grados Celsius y Fahrenheit es $F = \\dfrac{9}{5}C + 32$. ¿Cuántos grados Celsius corresponden a $59\\,^\\circ\\mathrm{F}$? Escribe solo el número, en $^\\circ\\mathrm{C}$.","answer":"15","why":"Reemplazamos: $59 = \\frac{9}{5}C + 32$. Restamos 32: $27 = \\frac{9}{5}C$; multiplicamos por $\\frac{5}{9}$: $C = 15$."},{"q":"La relación entre grados Celsius y Fahrenheit es $F = \\dfrac{9}{5}C + 32$. ¿Cuántos grados Celsius corresponden a $95\\,^\\circ\\mathrm{F}$?","options":["$\\dfrac{567}{5}\\,^\\circ\\mathrm{C}$","$63\\,^\\circ\\mathrm{C}$","$40\\,^\\circ\\mathrm{C}$","$35\\,^\\circ\\mathrm{C}$"],"correct":3,"why":"Reemplazamos: $95 = \\frac{9}{5}C + 32$. Restamos 32: $63 = \\frac{9}{5}C$; multiplicamos por $\\frac{5}{9}$: $C = 35$."},{"type":"input","kind":"number","q":"Un tanque tiene $38\\,\\mathrm{L}$ y se vacía a $2\\,\\mathrm{L}$ por minuto: $V = 38 - 2t$. ¿Cuántos minutos pasan hasta que quedan $28\\,\\mathrm{L}$? Escribe solo el número, en $\\mathrm{min}$.","answer":"5","why":"Restamos 38: $-2t = -10$; dividimos por $-2$: $t = 5$."},{"q":"Una vela mide $50\\,\\mathrm{cm}$ y se consume $5\\,\\mathrm{cm}$ por hora: $h = 50 - 5t$. ¿Cuántas horas pasan hasta que mide $30\\,\\mathrm{cm}$?","options":["$-4\\,\\mathrm{h}$","$16\\,\\mathrm{h}$","$4\\,\\mathrm{h}$","$20\\,\\mathrm{h}$"],"correct":2,"why":"Restamos 50: $-5t = -20$; dividimos por $-5$: $t = 4$."},{"type":"input","kind":"number","q":"Un cultivo tiene $69$ unidades de nutriente y consume $5$ por día: $n = 69 - 5t$. ¿Cuántos días pasan hasta que quedan $9$ unidades? Escribe solo el número, en $\\text{días}$.","answer":"12","why":"Restamos 69: $-5t = -60$; dividimos por $-5$: $t = 12$."},{"q":"Dos ciclistas salen en la misma dirección: el primero va a $6\\,\\mathrm{m/s}$ y el segundo, que parte $12\\,\\mathrm{m}$ adelante, va a $4\\,\\mathrm{m/s}$. Se encuentran cuando $6t = 4t + 12$. ¿Después de cuántos segundos?","options":["$6\\,\\mathrm{s}$","$2\\,\\mathrm{s}$","$\\dfrac{6}{5}\\,\\mathrm{s}$","$12\\,\\mathrm{s}$"],"correct":0,"why":"Igualamos: $6t = 4t + 12$. Entonces $2t = 12$ y $t = 6$."},{"type":"input","kind":"number","q":"Un robot A avanza $7\\,\\mathrm{cm}$ por segundo y un robot B, con $35\\,\\mathrm{cm}$ de ventaja, avanza $2\\,\\mathrm{cm}$ por segundo. A alcanza a B cuando $7t = 2t + 35$. ¿En cuántos segundos? Escribe solo el número, en $\\mathrm{s}$.","answer":"7","why":"Igualamos: $7t = 2t + 35$. Entonces $5t = 35$ y $t = 7$."},{"q":"Dos lanchas siguen la misma ruta: la rápida va a $5\\,\\mathrm{km/h}$ y la lenta, que salió $36\\,\\mathrm{km}$ antes, va a $1\\,\\mathrm{km/h}$. La rápida la alcanza cuando $5t = 1t + 36$. ¿Cuántas horas después?","options":["$36\\,\\mathrm{h}$","$9\\,\\mathrm{h}$","$6\\,\\mathrm{h}$","$\\dfrac{36}{5}\\,\\mathrm{h}$"],"correct":1,"why":"Igualamos: $5t = 1t + 36$. Entonces $4t = 36$ y $t = 9$."},{"type":"input","kind":"number","q":"En un cultivo A hay $0$ células y se agregan $7$ por hora; en B hay $10$ células y se agregan $2$ por hora. Hay igual cantidad cuando $7t = 2t + 10$. ¿Después de cuántas horas? Escribe solo el número, en $\\mathrm{h}$.","answer":"2","why":"Igualamos: $7t = 2t + 10$. Entonces $5t = 10$ y $t = 2$."},{"q":"Dos velas miden $28\\,\\mathrm{cm}$ y $20\\,\\mathrm{cm}$. La primera se consume $7\\,\\mathrm{cm}$ por hora y la segunda $5\\,\\mathrm{cm}$ por hora. Tienen la misma altura cuando $28 - 7t = 20 - 5t$. ¿Después de cuántas horas?","options":["$4\\,\\mathrm{h}$","$\\dfrac{2}{3}\\,\\mathrm{h}$","$8\\,\\mathrm{h}$","$5\\,\\mathrm{h}$"],"correct":0,"why":"Igualamos las alturas: $28 - 7t = 20 - 5t$. Entonces $2t = 8$ y $t = 4$."},{"q":"Dos tanques tienen $39\\,\\mathrm{L}$ y $18\\,\\mathrm{L}$ y se vacían a $9\\,\\mathrm{L}$ y $6\\,\\mathrm{L}$ por hora. Tienen igual volumen cuando $39 - 9t = 18 - 6t$. ¿Después de cuántas horas?","options":["$8\\,\\mathrm{h}$","$7\\,\\mathrm{h}$","$\\dfrac{7}{5}\\,\\mathrm{h}$","$21\\,\\mathrm{h}$"],"correct":1,"why":"Igualamos las alturas: $39 - 9t = 18 - 6t$. Entonces $3t = 21$ y $t = 7$."},{"q":"Un resorte tiene largo natural de $11\\,\\mathrm{cm}$. Al estirarlo, la fuerza (en N) cumple $6(L - 11) = 12$, donde $L$ es su largo en cm. ¿Cuánto mide el resorte estirado?","options":["$23\\,\\mathrm{cm}$","$2\\,\\mathrm{cm}$","$13\\,\\mathrm{cm}$","$14\\,\\mathrm{cm}$"],"correct":2,"why":"Dividimos por 6: $L - 11 = 2$, luego $L = 13$."},{"q":"Un resorte de largo natural $5\\,\\mathrm{cm}$ ejerce una fuerza que cumple $3(L - 5) = 18$ (con $L$ en cm). ¿Cuál es el largo $L$ del resorte?","options":["$11\\,\\mathrm{cm}$","$23\\,\\mathrm{cm}$","$12\\,\\mathrm{cm}$","$6\\,\\mathrm{cm}$"],"correct":0,"why":"Dividimos por 3: $L - 5 = 6$, luego $L = 11$."}],"drawCheck":5,"unit":0},{"id":"u3-s003","title":"Paréntesis y fracciones","subtitle":"Simplificar antes de despejar","group":0,"symbol":"✧","minutes":50,"concept":"Si la ecuación tiene paréntesis, se eliminan primero aplicando la propiedad distributiva: $a(b + c) = ab + ac$. Si tiene fracciones, se multiplica toda la ecuación por el mínimo común múltiplo de los denominadores; así desaparecen los denominadores y queda una ecuación lineal sin fracciones.\n\nEn ambos casos, lo importante es hacer la misma operación en todos los términos de los dos lados.","example":"Resolvemos $\\frac{x}{3} + \\frac{1}{2} = \\frac{5}{6}$. El mínimo común múltiplo de 3, 2 y 6 es 6; multiplicamos todo por 6:\n$$2x + 3 = 5 \\quad\\Rightarrow\\quad 2x = 2 \\quad\\Rightarrow\\quad x = 1$$\nVerificamos: $\\frac{1}{3} + \\frac{1}{2} = \\frac{2}{6} + \\frac{3}{6} = \\frac{5}{6}$.","media":[],"practice":[{"type":"input","kind":"number","q":"Resuelve la ecuación:\n$$2(x - 3) = 10$$\n\nEscribe el valor de $x$.","answer":"8","why":"Dividimos ambos lados por 2 y luego sumamos 3: $x - 3 = 5$, de donde $x = 8$."},{"q":"Resuelve la ecuación:\n$$\\frac{x}{3} + \\frac{1}{2} = \\frac{5}{6}$$","options":["$x = 3$","$x = \\tfrac{1}{9}$","$x = 1$"],"correct":2,"why":"Multiplicamos toda la ecuación por 6, el mínimo común múltiplo: $2x + 3 = 5$, luego $2x = 2$ y $x = 1$."},{"type":"input","kind":"number","q":"Resuelve la ecuación:\n$$6(x + 4) = 48$$\n\nEscribe el valor de $x$.","answer":"4","why":"Dividimos por 6: $x + 4 = 8$, y despejamos: $x = 4$."},{"q":"Resuelve la ecuación:\n$$3(x - 1) = 21$$","options":["$x=\\dfrac{22}{3}$","$x=8$","$x=7$","$x=6$"],"correct":1,"why":"Dividimos por 3: $x - 1 = 7$, y despejamos: $x = 8$."},{"type":"input","kind":"number","q":"Resuelve la ecuación:\n$$6(x - 5) = 24$$\n\nEscribe el valor de $x$.","answer":"9","why":"Dividimos por 6: $x - 5 = 4$, y despejamos: $x = 9$."},{"q":"Resuelve la ecuación:\n$$4(x + 6) + 2 = 34$$","options":["$x=3$","$x=8$","$x=14$","$x=2$"],"correct":3,"why":"Restamos 2: $4(x + 6) = 32$. Distribuimos: $4x + 24 = 32$, y despejando $x = 2$."},{"type":"input","kind":"number","q":"Resuelve la ecuación:\n$$2(x + 4) + 3 = 23$$\n\nEscribe el valor de $x$.","answer":"6","why":"Restamos 3: $2(x + 4) = 20$. Distribuimos: $2x + 8 = 20$, y despejando $x = 6$."},{"q":"Resuelve la ecuación:\n$$2(x + 5) + 1 = 17$$","options":["$x=13$","$x=4$","$x=3$","$x=8$"],"correct":2,"why":"Restamos 1: $2(x + 5) = 16$. Distribuimos: $2x + 10 = 16$, y despejando $x = 3$."},{"type":"input","kind":"number","q":"Resuelve la ecuación:\n$$5(x + 1) = x + 13$$\n\nEscribe el valor de $x$.","answer":"2","why":"Distribuimos: $5x + 5 = x + 13$. Agrupamos: $4x = 8$, así que $x = 2$."},{"q":"Resuelve la ecuación:\n$$7(x + 1) = x + 49$$","options":["$x=7$","$x=-7$","$x=\\dfrac{21}{4}$","$x=\\dfrac{28}{3}$"],"correct":0,"why":"Distribuimos: $7x + 7 = x + 49$. Agrupamos: $6x = 42$, así que $x = 7$."},{"type":"input","kind":"number","q":"Resuelve la ecuación:\n$$3(x + 4) = x + 18$$\n\nEscribe el valor de $x$.","answer":"3","why":"Distribuimos: $3x + 12 = x + 18$. Agrupamos: $2x = 6$, así que $x = 3$."},{"q":"Resuelve la ecuación:\n$$\\frac{x}{4} + 4 = 8$$","options":["$x=16$","$x=48$","$x=1$","$x=4$"],"correct":0,"why":"Restamos 4: $\\frac{x}{4} = 4$. Multiplicamos por 4: $x = 16$."},{"type":"input","kind":"number","q":"Resuelve la ecuación:\n$$\\frac{x}{3} + 1 = 2$$\n\nEscribe el valor de $x$.","answer":"3","why":"Restamos 1: $\\frac{x}{3} = 1$. Multiplicamos por 3: $x = 3$."},{"q":"Resuelve la ecuación:\n$$\\frac{x}{5} + 1 = 6$$","options":["$x=1$","$x=5$","$x=35$","$x=25$"],"correct":3,"why":"Restamos 1: $\\frac{x}{5} = 5$. Multiplicamos por 5: $x = 25$."},{"type":"input","kind":"number","q":"Resuelve la ecuación:\n$$\\frac{x}{2} + \\frac{x}{3} = 15$$\n\nEscribe el valor de $x$.","answer":"18","why":"Multiplicamos por 6 (mínimo común múltiplo): $3x + 2x = 90$, es decir $5x = 90$, y $x = 18$."},{"q":"Resuelve la ecuación:\n$$\\frac{x}{3} + \\frac{x}{4} = 7$$","options":["$x=84$","$x=12$","$x=49$","$x=1$"],"correct":1,"why":"Multiplicamos por 12 (mínimo común múltiplo): $4x + 3x = 84$, es decir $7x = 84$, y $x = 12$."},{"q":"Resuelve la ecuación:\n$$\\frac{x + 11}{3} = 6$$","options":["$x=-5$","$x=-\\dfrac{5}{3}$","$x=29$","$x=7$"],"correct":3,"why":"Multiplicamos por 3: $x + 11 = 18$, y despejamos: $x = 7$."},{"q":"Resuelve la ecuación:\n$$\\frac{x + 20}{4} = 7$$","options":["$x=8$","$x=-13$","$x=-\\dfrac{13}{4}$","$x=48$"],"correct":0,"why":"Multiplicamos por 4: $x + 20 = 28$, y despejamos: $x = 8$."},{"q":"Al aplicar la propiedad distributiva a $4(x - 1)$ se obtiene:","options":["$4x - 1$","$x - 4$","$4x + 4$","$4x - 4$"],"correct":3,"why":"Multiplicamos 4 por cada término del paréntesis: $4 \\cdot x - 4 \\cdot 1$."},{"q":"Al aplicar la propiedad distributiva a $2(x + 7)$ se obtiene:","options":["$2x + 7$","$2x + 14$","$x + 14$","$2x - 14$"],"correct":1,"why":"Multiplicamos 2 por cada término del paréntesis: $2 \\cdot x + 2 \\cdot 7$."}],"check":{"q":"Se prepara una solución de volumen total $V$ (en mL). Los tres cuartos del volumen total corresponden a 18 mL de agua, es decir, $\\frac{3}{4}V = 18$. ¿Cuál es el volumen total de la solución?","options":["$V = 24\\,\\mathrm{mL}$","$V = 13{,}5\\,\\mathrm{mL}$","$V = 72\\,\\mathrm{mL}$"],"correct":0,"why":"Multiplicamos por el inverso de la fracción: $V = 18 \\cdot \\frac{4}{3} = 24$."},"draw":5,"checks":[{"type":"input","kind":"number","q":"Se reparten $x + 1\\,\\mathrm{mL}$ de reactivo a cada uno de $4$ tubos y se usan $12\\,\\mathrm{mL}$ en total: $4(x + 1) = 12$. ¿Cuánto es $x$ (en mL)?","answer":"2","why":"Dividimos por 4: $x + 1 = 3$; entonces $x = 2$."},{"q":"Cada una de $2$ jaulas recibe $(x + 4)$ gramos de alimento y se entregan $20$ gramos en total: $2(x + 4) = 20$. ¿Cuánto vale $x$?","options":["$10$","$14$","$6$","$8$"],"correct":2,"why":"Dividimos por 2: $x + 4 = 10$; entonces $x = 6$."},{"type":"input","kind":"number","q":"Un grupo de $4$ estudiantes mide, cada uno, $(x + 2)$ plantas y registran $36$ en total: $4(x + 2) = 36$. ¿Cuánto vale $x$?","answer":"7","why":"Dividimos por 4: $x + 2 = 9$; entonces $x = 7$."},{"q":"Cada uno de $5$ recipientes pierde $1\\,\\mathrm{mL}$ por evaporación y queda con $(x - 1)\\,\\mathrm{mL}$. En total quedan $10\\,\\mathrm{mL}$: $5(x - 1) = 10$. ¿Cuántos mL tenía inicialmente cada recipiente?","options":["$2$","$\\dfrac{11}{5}$","$3$","$1$"],"correct":2,"why":"Dividimos por 5: $x - 1 = 2$; entonces $x = 3$."},{"type":"input","kind":"number","q":"En $5$ parcelas se cosecha $(x - 2)$ kg por parcela, con un total de $35$ kg: $5(x - 2) = 35$. ¿Cuánto vale $x$?","answer":"9","why":"Dividimos por 5: $x - 2 = 7$; entonces $x = 9$."},{"q":"Cada una de $5$ muestras pierde $5\\,\\mathrm{g}$ al secarse y queda con $(x - 5)\\,\\mathrm{g}$. Quedan $50\\,\\mathrm{g}$ en total: $5(x - 5) = 50$. ¿Cuánto pesaba cada muestra antes?","options":["$5$","$15$","$11$","$10$"],"correct":1,"why":"Dividimos por 5: $x - 5 = 10$; entonces $x = 15$."},{"type":"input","kind":"number","q":"La temperatura media de $4$ mediciones es $25\\,^\\circ\\mathrm{C}$. Se conocen $3$ de ellas: $26 + 23 + 29$ (en $^\\circ\\mathrm{C}$). Si la medición que falta es $x$, se cumple $\\dfrac{x + 26 + 23 + 29}{4} = 25$. ¿Cuánto vale $x$? Escribe solo el número, en $^\\circ\\mathrm{C}$.","answer":"22","why":"Multiplicamos por 4: $x + 26 + 23 + 29 = 100$. Entonces $x = 100 - 78 = 22$."},{"q":"La masa media de $3$ muestras es $17\\,\\mathrm{g}$. Se conocen $2$ masas: $17 + 17$ (en g). Para la que falta, $\\dfrac{x + 17 + 17}{3} = 17$. ¿Cuánto pesa la muestra faltante?","options":["$20\\,\\mathrm{g}$","$17\\,\\mathrm{g}$","$85\\,\\mathrm{g}$","$51\\,\\mathrm{g}$"],"correct":1,"why":"Multiplicamos por 3: $x + 17 + 17 = 51$. Entonces $x = 51 - 34 = 17$."},{"type":"input","kind":"number","q":"El pH medio de $4$ soluciones es $16$ en una escala ficticia. Se conocen $3$ valores: $15 + 18 + 13$. Para el que falta, $\\dfrac{x + 15 + 18 + 13}{4} = 16$. ¿Cuánto vale $x$?","answer":"18","why":"Multiplicamos por 4: $x + 15 + 18 + 13 = 64$. Entonces $x = 64 - 46 = 18$."},{"q":"La altura media de $5$ plantas es $21\\,\\mathrm{cm}$. Se conocen $4$ alturas: $20 + 25 + 22 + 24$ (en cm). Para la que falta, $\\dfrac{x + 20 + 25 + 22 + 24}{5} = 21$. ¿Cuánto mide esa planta?","options":["$105\\,\\mathrm{cm}$","$14\\,\\mathrm{cm}$","$21\\,\\mathrm{cm}$","$19\\,\\mathrm{cm}$"],"correct":1,"why":"Multiplicamos por 5: $x + 20 + 25 + 22 + 24 = 105$. Entonces $x = 105 - 91 = 14$."},{"type":"input","kind":"number","q":"La cuarta parte del volumen de una muestra, más $8\\,\\mathrm{mL}$ de agua, da $20\\,\\mathrm{mL}$: $\\dfrac{x}{4} + 8 = 20$. ¿Cuál es el volumen $x$ de la muestra? Escribe solo el número, en $\\mathrm{mL}$.","answer":"48","why":"Restamos 8: $\\frac{x}{4} = 12$. Multiplicamos por 4: $x = 48$."},{"q":"Si a la mitad de la masa de un cristal se le suman $6\\,\\mathrm{g}$, se obtienen $9\\,\\mathrm{g}$: $\\dfrac{x}{2} + 6 = 9$. ¿Cuál es la masa $x$ del cristal?","options":["$\\dfrac{3}{2}\\,\\mathrm{g}$","$6\\,\\mathrm{g}$","$30\\,\\mathrm{g}$","$3\\,\\mathrm{g}$"],"correct":1,"why":"Restamos 6: $\\frac{x}{2} = 3$. Multiplicamos por 2: $x = 6$."},{"type":"input","kind":"number","q":"La sexta parte de una distancia recorrida, más $7\\,\\mathrm{m}$, es $13\\,\\mathrm{m}$: $\\dfrac{x}{6} + 7 = 13$. ¿Cuál fue la distancia $x$? Escribe solo el número, en $\\mathrm{m}$.","answer":"36","why":"Restamos 7: $\\frac{x}{6} = 6$. Multiplicamos por 6: $x = 36$."},{"q":"Una llave llena un tanque en $10$ horas y otra lo llena en $15$ horas. Si ambas están abiertas, el tiempo $t$ cumple $\\dfrac{t}{10} + \\dfrac{t}{15} = 1$. ¿Cuántas horas tardan juntas?","options":["$6\\,\\mathrm{h}$","$150\\,\\mathrm{h}$","$25\\,\\mathrm{h}$","$\\dfrac{25}{2}\\,\\mathrm{h}$"],"correct":0,"why":"Multiplicamos por el mínimo común múltiplo: se obtiene $t = 6$ horas."},{"type":"input","kind":"number","q":"Una bomba vacía un estanque en $12$ horas y otra lo vacía en $4$ horas. Trabajando juntas, $\\dfrac{t}{12} + \\dfrac{t}{4} = 1$. ¿Cuántas horas tardan en vaciarlo? Escribe solo el número, en $\\mathrm{h}$.","answer":"3","why":"Multiplicamos por el mínimo común múltiplo: se obtiene $t = 3$ horas."},{"q":"Un técnico limpia un laboratorio en $10$ horas y su ayudante en $15$ horas. Juntos, $\\dfrac{t}{10} + \\dfrac{t}{15} = 1$. ¿Cuántas horas tardan?","options":["$6\\,\\mathrm{h}$","$150\\,\\mathrm{h}$","$\\dfrac{25}{2}\\,\\mathrm{h}$","$25\\,\\mathrm{h}$"],"correct":0,"why":"Multiplicamos por el mínimo común múltiplo: se obtiene $t = 6$ horas."},{"q":"Una dosis $x$ (en mg) cumple que su $\\dfrac{1}{3}$ menos su $\\dfrac{1}{4}$ es igual a $5\\,\\mathrm{mg}$, es decir $\\dfrac{x}{3} - \\dfrac{x}{4} = 5$. ¿Cuánto vale $x$?","options":["$57\\,\\mathrm{mg}$","$35\\,\\mathrm{mg}$","$65\\,\\mathrm{mg}$","$60\\,\\mathrm{mg}$"],"correct":3,"why":"Multiplicamos por 12 (múltiplo común): $4x - 3x = 60$; luego $x = 60$."},{"q":"De un volumen $x$ de gas, la $\\dfrac{1}{3}$ parte menos la $\\dfrac{1}{6}$ parte es $12\\,\\mathrm{L}$: $\\dfrac{x}{3} - \\dfrac{x}{6} = 12$. ¿Cuánto vale $x$ en litros?","options":["$72\\,\\mathrm{L}$","$108\\,\\mathrm{L}$","$84\\,\\mathrm{L}$","$216\\,\\mathrm{L}$"],"correct":0,"why":"Multiplicamos por 18 (múltiplo común): $6x - 3x = 216$; luego $x = 72$."},{"q":"De una masa $x$, la $\\dfrac{1}{2}$ parte menos la $\\dfrac{1}{3}$ parte es $1\\,\\mathrm{g}$: $\\dfrac{x}{2} - \\dfrac{x}{3} = 1$. ¿Cuánto vale $x$ en gramos?","options":["$4\\,\\mathrm{g}$","$7\\,\\mathrm{g}$","$6\\,\\mathrm{g}$","$5\\,\\mathrm{g}$"],"correct":2,"why":"Multiplicamos por 6 (múltiplo común): $3x - 2x = 6$; luego $x = 6$."}],"drawCheck":5,"unit":0},{"id":"u3-s004","title":"Despeje de fórmulas","subtitle":"Cambiar la incógnita","group":0,"symbol":"✧","minutes":40,"concept":"Muchas fórmulas de ciencias son ecuaciones con varias letras. Despejar una letra significa dejarla sola en un lado de la igualdad, con los mismos pasos que usas en una ecuación con números.\n\nLas demás letras se tratan como si fueran números conocidos, y se aplican las operaciones inversas en ambos lados de la igualdad.","example":"Despejamos $v$ en la fórmula de la rapidez media $d = vt$ (con $t \\neq 0$). Dividimos ambos lados por $t$:\n$$v = \\frac{d}{t}$$\nPor ejemplo, si $d = 120\\,\\mathrm{km}$ y $t = 2\\,\\mathrm{h}$, entonces $v = 60\\,\\mathrm{km/h}$.","media":[],"practice":[{"q":"Despeja $x$ en la ecuación:\n$$y = mx + n$$","options":["$x = \\dfrac{y}{m} - n$","$x = \\dfrac{y - n}{m}$","$x = m(y - n)$"],"correct":1,"why":"Primero restamos $n$ a ambos lados y luego dividimos todo por $m$: $y - n = mx$, de donde $x = \\frac{y - n}{m}$."},{"q":"Despeja $t$ en la ecuación:\n$$d = vt$$","options":["$t = \\dfrac{d}{v}$","$t = dv$","$t = d - v$"],"correct":0,"why":"Dividimos ambos lados por $v$: $t = \\frac{d}{v}$."},{"q":"Despeja $m$ en la fórmula:\n$$y = mx + n$$","options":["$m = x(y - n)$","$m = \\dfrac{y + n}{x}$","$m = \\dfrac{y}{x} - n$","$m = \\dfrac{y - n}{x}$"],"correct":3,"why":"Restamos $n$ y dividimos por $x$."},{"q":"Despeja $t$ en la fórmula:\n$$v = \\dfrac{d}{t}$$","options":["$t = \\dfrac{d}{v}$","$t = \\dfrac{v}{d}$","$t = d - v$","$t = dv$"],"correct":0,"why":"Multiplicamos por $t$: $vt = d$; luego dividimos por $v$."},{"q":"Despeja $h$ en la fórmula:\n$$A = bh$$","options":["$h = \\dfrac{b}{A}$","$h = Ab$","$h = \\dfrac{A}{b}$","$h = A - b$"],"correct":2,"why":"Dividimos ambos lados por $b$."},{"q":"Despeja $h$ en la fórmula:\n$$A = \\dfrac{bh}{2}$$","options":["$h = \\dfrac{2A}{b}$","$h = 2Ab$","$h = \\dfrac{A}{b} - 2$","$h = \\dfrac{A}{2b}$"],"correct":0,"why":"Multiplicamos por 2: $2A = bh$; luego dividimos por $b$."},{"q":"Despeja $l$ en la fórmula:\n$$P = 2l + 2a$$","options":["$l = \\dfrac{P}{2} - 2a$","$l = \\dfrac{P - 2a}{2}$","$l = P - a$","$l = \\dfrac{P + 2a}{2}$"],"correct":1,"why":"Restamos $2a$ y dividimos todo por 2."},{"q":"Despeja $a$ en la fórmula:\n$$F = ma$$","options":["$a = Fm$","$a = F - m$","$a = \\dfrac{m}{F}$","$a = \\dfrac{F}{m}$"],"correct":3,"why":"Dividimos por $m$ (segunda ley de Newton)."},{"q":"Despeja $h$ en la fórmula:\n$$V = lah$$","options":["$h = \\dfrac{la}{V}$","$h = \\dfrac{V}{la}$","$h = Vla$","$h = \\dfrac{V}{l} - a$"],"correct":1,"why":"Dividimos por el producto $la$."},{"q":"Despeja $t$ en la fórmula:\n$$v = v_0 + at$$","options":["$t = \\dfrac{v}{a} - v_0$","$t = \\dfrac{v + v_0}{a}$","$t = \\dfrac{v - v_0}{a}$","$t = a(v - v_0)$"],"correct":2,"why":"Restamos $v_0$ y dividimos por $a$."},{"q":"Despeja $a$ en la fórmula:\n$$v = v_0 + at$$","options":["$a = \\dfrac{v + v_0}{t}$","$a = \\dfrac{v}{t} - v_0$","$a = (v - v_0)t$","$a = \\dfrac{v - v_0}{t}$"],"correct":3,"why":"Restamos $v_0$ y dividimos por $t$."},{"q":"Despeja $v$ en la fórmula:\n$$d = d_0 + vt$$","options":["$v = \\dfrac{d + d_0}{t}$","$v = (d - d_0)t$","$v = \\dfrac{d}{t} - d_0$","$v = \\dfrac{d - d_0}{t}$"],"correct":3,"why":"Restamos $d_0$ y dividimos por $t$."},{"q":"Despeja $R$ en la fórmula:\n$$V = IR$$","options":["$R = V - I$","$R = \\dfrac{V}{I}$","$R = \\dfrac{I}{V}$","$R = VI$"],"correct":1,"why":"Ley de Ohm: dividimos por $I$."},{"q":"Despeja $C$ en la fórmula:\n$$F = \\dfrac{9}{5}C + 32$$","options":["$C = \\dfrac{5(F - 32)}{9}$","$C = \\dfrac{5(F + 32)}{9}$","$C = \\dfrac{9(F - 32)}{5}$","$C = \\dfrac{5F - 32}{9}$"],"correct":0,"why":"Restamos 32 y multiplicamos por $\\frac{5}{9}$."},{"q":"Despeja $C$ en la fórmula:\n$$K = C + 273$$","options":["$C = K - 273$","$C = \\dfrac{K}{273}$","$C = K + 273$","$C = 273 - K$"],"correct":0,"why":"Restamos 273 a ambos lados."},{"q":"Despeja $y$ en la fórmula:\n$$ax + by = c$$","options":["$y = c - ax - b$","$y = \\dfrac{ax - c}{b}$","$y = \\dfrac{c - ax}{b}$","$y = \\dfrac{c + ax}{b}$"],"correct":2,"why":"Restamos $ax$ y dividimos por $b$."},{"q":"Despeja $h$ en la fórmula:\n$$A = \\dfrac{(B + b)h}{2}$$","options":["$h = 2A(B + b)$","$h = \\dfrac{2A}{B} + b$","$h = \\dfrac{A}{2(B + b)}$","$h = \\dfrac{2A}{B + b}$"],"correct":3,"why":"Multiplicamos por 2 y dividimos por $(B + b)$."},{"q":"Despeja $B$ en la fórmula:\n$$A = \\dfrac{(B + b)h}{2}$$","options":["$B = \\dfrac{2A}{h} + b$","$B = \\dfrac{2A}{h} - b$","$B = \\dfrac{A}{2h} - b$","$B = \\dfrac{2A - b}{h}$"],"correct":1,"why":"Multiplicamos por 2, dividimos por $h$ y restamos $b$."},{"q":"Despeja $m$ en la fórmula:\n$$Q = mcT$$","options":["$m = QcT$","$m = \\dfrac{cT}{Q}$","$m = \\dfrac{Q}{cT}$","$m = \\dfrac{Q}{c} - T$"],"correct":2,"why":"Dividimos por el producto $cT$."},{"q":"Despeja $x$ en la fórmula:\n$$\\dfrac{x}{a} = \\dfrac{y}{b}$$","options":["$x = \\dfrac{by}{a}$","$x = a + \\dfrac{y}{b}$","$x = \\dfrac{ay}{b}$","$x = \\dfrac{y}{ab}$"],"correct":2,"why":"Multiplicamos ambos lados por $a$."}],"check":{"q":"La ecuación de los gases ideales relaciona presión, volumen, cantidad de sustancia y temperatura:\n$$PV = nRT$$\n¿Cuál es la expresión correcta para la temperatura $T$?","options":["$T = PVnR$","$T = \\dfrac{nR}{PV}$","$T = \\dfrac{PV}{nR}$"],"correct":2,"why":"Dividimos ambos lados por el producto $nR$: $T = \\frac{PV}{nR}$."},"draw":5,"checks":[{"q":"En química, la ley de los gases ideales es $PV = nRT$. Despeja $V$.","options":["$V = nRTP$","$V = \\dfrac{P}{nRT}$","$V = \\dfrac{nR}{PT}$","$V = \\dfrac{nRT}{P}$"],"correct":3,"why":"Dividimos ambos lados por $P$."},{"q":"En la ley de los gases ideales $PV = nRT$, despeja la temperatura $T$.","options":["$T = \\dfrac{PV}{n} - R$","$T = \\dfrac{PV}{nR}$","$T = PVnR$","$T = \\dfrac{nR}{PV}$"],"correct":1,"why":"Dividimos por el producto $nR$."},{"q":"En la ley de los gases ideales $PV = nRT$, despeja la cantidad de sustancia $n$.","options":["$n = PV - RT$","$n = \\dfrac{PV}{RT}$","$n = \\dfrac{PV}{R} + T$","$n = \\dfrac{RT}{PV}$"],"correct":1,"why":"Dividimos por el producto $RT$."},{"q":"La densidad de una sustancia es $\\rho = \\dfrac{m}{V}$. Despeja el volumen $V$.","options":["$V = \\dfrac{m}{\\rho}$","$V = m\\rho$","$V = \\dfrac{\\rho}{m}$","$V = m - \\rho$"],"correct":0,"why":"Multiplicamos por $V$ y luego dividimos por $\\rho$."},{"q":"La densidad es $\\rho = \\dfrac{m}{V}$. Despeja la masa $m$.","options":["$m = \\dfrac{\\rho}{V}$","$m = \\rho V$","$m = \\rho + V$","$m = \\dfrac{V}{\\rho}$"],"correct":1,"why":"Multiplicamos ambos lados por $V$."},{"q":"El calor necesario para cambiar la temperatura de una masa es $Q = mc\\Delta T$. Despeja el calor específico $c$.","options":["$c = Q - m\\Delta T$","$c = \\dfrac{Q}{m} - \\Delta T$","$c = \\dfrac{m\\Delta T}{Q}$","$c = \\dfrac{Q}{m\\Delta T}$"],"correct":3,"why":"Dividimos por el producto $m\\Delta T$."},{"q":"En $Q = mc\\Delta T$, despeja la variación de temperatura $\\Delta T$.","options":["$\\Delta T = Q - mc$","$\\Delta T = \\dfrac{mc}{Q}$","$\\Delta T = \\dfrac{Q}{mc}$","$\\Delta T = \\dfrac{Q}{m} - c$"],"correct":2,"why":"Dividimos por el producto $mc$."},{"q":"La ley de Ohm es $V = IR$. Despeja la corriente $I$.","options":["$I = \\dfrac{V}{R}$","$I = \\dfrac{R}{V}$","$I = V - R$","$I = VR$"],"correct":0,"why":"Dividimos ambos lados por $R$."},{"q":"La potencia eléctrica es $P = VI$. Despeja el voltaje $V$.","options":["$V = \\dfrac{I}{P}$","$V = PI$","$V = \\dfrac{P}{I}$","$V = P - I$"],"correct":2,"why":"Dividimos ambos lados por $I$."},{"q":"El trabajo realizado por una fuerza constante es $W = Fd$. Despeja la distancia $d$.","options":["$d = W - F$","$d = \\dfrac{W}{F}$","$d = WF$","$d = \\dfrac{F}{W}$"],"correct":1,"why":"Dividimos ambos lados por $F$."},{"q":"La velocidad media es $v = \\dfrac{d}{t}$. Despeja la distancia $d$.","options":["$d = \\dfrac{v}{t}$","$d = vt$","$d = v + t$","$d = \\dfrac{t}{v}$"],"correct":1,"why":"Multiplicamos ambos lados por $t$."},{"q":"En un movimiento con aceleración constante, $v = v_0 + at$. Despeja la velocidad inicial $v_0$.","options":["$v_0 = v + at$","$v_0 = \\dfrac{v}{at}$","$v_0 = v - at$","$v_0 = at - v$"],"correct":2,"why":"Restamos $at$ a ambos lados."},{"q":"En $v = v_0 + at$, despeja el tiempo $t$.","options":["$t = \\dfrac{v - v_0}{a}$","$t = \\dfrac{v + v_0}{a}$","$t = \\dfrac{v}{a} - v_0$","$t = a(v - v_0)$"],"correct":0,"why":"Restamos $v_0$ y dividimos por $a$."},{"q":"La ley de Hooke para un resorte es $F = kx$. Despeja la constante $k$.","options":["$k = \\dfrac{x}{F}$","$k = F - x$","$k = \\dfrac{F}{x}$","$k = Fx$"],"correct":2,"why":"Dividimos ambos lados por $x$."},{"q":"La molaridad de una solución es $M = \\dfrac{n}{V}$. Despeja la cantidad de sustancia $n$.","options":["$n = \\dfrac{M}{V}$","$n = \\dfrac{V}{M}$","$n = M + V$","$n = MV$"],"correct":3,"why":"Multiplicamos ambos lados por $V$."},{"q":"La presión es $p = \\dfrac{F}{A}$. Despeja el área $A$.","options":["$A = F - p$","$A = Fp$","$A = \\dfrac{F}{p}$","$A = \\dfrac{p}{F}$"],"correct":2,"why":"Multiplicamos por $A$ y luego dividimos por $p$."},{"q":"En química, $\\mathrm{pH} + \\mathrm{pOH} = 14$. Despeja $\\mathrm{pOH}$.","options":["$\\mathrm{pOH} = \\dfrac{14}{\\mathrm{pH}}$","$\\mathrm{pOH} = 14 + \\mathrm{pH}$","$\\mathrm{pOH} = \\mathrm{pH} - 14$","$\\mathrm{pOH} = 14 - \\mathrm{pH}$"],"correct":3,"why":"Restamos pH a ambos lados."},{"q":"El calor necesario para fundir una sustancia es $Q = mL$. Despeja el calor latente $L$.","options":["$L = \\dfrac{Q}{m}$","$L = Q - m$","$L = Qm$","$L = \\dfrac{m}{Q}$"],"correct":0,"why":"Dividimos ambos lados por $m$."},{"q":"La cantidad de movimiento es $p = mv$. Despeja la velocidad $v$.","options":["$v = pm$","$v = \\dfrac{m}{p}$","$v = \\dfrac{p}{m}$","$v = p - m$"],"correct":2,"why":"Dividimos ambos lados por $m$."}],"drawCheck":5,"unit":0},{"id":"u3-s005","title":"Del enunciado a la ecuación","subtitle":"Traducir a lenguaje algebraico","group":1,"symbol":"✧","minutes":40,"concept":"Para resolver un problema con una ecuación, primero se traduce el enunciado a lenguaje algebraico: se elige una letra para la cantidad desconocida y se expresan las relaciones del texto con operaciones.\n\nAlgunas traducciones frecuentes: «el doble de un número» es $2x$; «un número aumentado en 5» es $x + 5$; «tres números consecutivos» son $x$, $x + 1$ y $x + 2$; «es igual a» o «resulta» se escribe con el signo $=$.","example":"Enunciado: el triple de un número, disminuido en 4, es igual a 20. Si el número es $x$, «el triple» es $3x$ y «disminuido en 4» es $-4$, de modo que la ecuación es\n$$3x - 4 = 20$$","media":[],"practice":[{"q":"El doble de un número, aumentado en 5, es igual a 17. ¿Qué ecuación representa esta situación?","options":["$2(x + 5) = 17$","$2x + 5 = 17$","$x + 10 = 17$"],"correct":1,"why":"El doble del número es $2x$, y a ese resultado se le suma 5: $2x + 5 = 17$."},{"q":"La suma de tres números enteros consecutivos es 48. Si el menor es $x$, ¿qué ecuación representa esta situación?","options":["$3x = 48$","$x(x + 1)(x + 2) = 48$","$x + (x + 1) + (x + 2) = 48$"],"correct":2,"why":"Los consecutivos son $x$, $x + 1$ y $x + 2$, y el enunciado habla de su suma."},{"q":"El triple de un número, aumentado en 3, es igual a 38. ¿Qué ecuación representa esta situación?","options":["$3x - 3 = 38$","$3x + 3 = 38$","$3(x + 3) = 38$","$x + 9 = 38$"],"correct":1,"why":"El triple del número es $3x$; luego se le suma 3: $3x + 3 = 38$."},{"q":"El cuádruple de un número, aumentado en 2, es igual a 37. ¿Qué ecuación representa esta situación?","options":["$4(x + 2) = 37$","$4x + 2 = 37$","$4x - 2 = 37$","$x + 8 = 37$"],"correct":1,"why":"El cuádruple del número es $4x$; luego se le suma 2: $4x + 2 = 37$."},{"q":"El doble de un número, disminuido en 5, es igual a 33. ¿Qué ecuación representa esta situación?","options":["$2x + 5 = 33$","$5 - 2x = 33$","$2x - 5 = 33$","$2(x - 5) = 33$"],"correct":2,"why":"Primero se calcula el doble, $2x$, y luego se le restan 5."},{"q":"El doble de un número, disminuido en 4, es igual a 12. ¿Qué ecuación representa esta situación?","options":["$2(x - 4) = 12$","$2x - 4 = 12$","$2x + 4 = 12$","$4 - 2x = 12$"],"correct":1,"why":"Primero se calcula el doble, $2x$, y luego se le restan 4."},{"q":"El doble de la suma de un número y 3 es igual a 22. ¿Qué ecuación representa esta situación?","options":["$2 + x + 3 = 22$","$2(x + 3) = 22$","$x + 6 = 22$","$2x + 3 = 22$"],"correct":1,"why":"La suma $x + 3$ se multiplica completa por 2, por eso va entre paréntesis."},{"q":"El triple de la suma de un número y 2 es igual a 24. ¿Qué ecuación representa esta situación?","options":["$3(x + 2) = 24$","$x + 6 = 24$","$3 + x + 2 = 24$","$3x + 2 = 24$"],"correct":0,"why":"La suma $x + 2$ se multiplica completa por 3, por eso va entre paréntesis."},{"q":"La suma de un número y su tercera parte es igual a 38. ¿Qué ecuación representa esta situación?","options":["$\\dfrac{x}{3} = 38$","$x + \\dfrac{x}{3} = 38$","$x + 3 = 38$","$x + 3x = 38$"],"correct":1,"why":"El número es $x$ y su tercera parte es $\\dfrac{x}{3}$; la suma es $x + \\dfrac{x}{3} = 38$."},{"q":"La suma de un número y su cuarta parte es igual a 41. ¿Qué ecuación representa esta situación?","options":["$x + 4x = 41$","$x + 4 = 41$","$\\dfrac{x}{4} = 41$","$x + \\dfrac{x}{4} = 41$"],"correct":3,"why":"El número es $x$ y su cuarta parte es $\\dfrac{x}{4}$; la suma es $x + \\dfrac{x}{4} = 41$."},{"q":"La suma de dos números enteros pares consecutivos es 41. Si el menor es $x$, ¿qué ecuación representa esta situación?","options":["$x + x + 4 = 41$","$x + (x + 1) = 41$","$x + (x + 2) = 41$","$x(x + 2) = 41$"],"correct":2,"why":"Si el menor es $x$, el siguiente es $x + 2$; se suman: $x + (x + 2) = 41$."},{"q":"La suma de dos números enteros consecutivos es 80. Si el menor es $x$, ¿qué ecuación representa esta situación?","options":["$x + (x + 1) = 80$","$x + (x + 2) = 80$","$2x + 2 = 80$","$x(x + 1) = 80$"],"correct":0,"why":"Si el menor es $x$, el siguiente es $x + 1$; se suman: $x + (x + 1) = 80$."},{"q":"Pedro tiene 2 años más que Ana, y entre los dos suman 59 años. Si Ana tiene $x$ años, ¿qué ecuación representa esta situación?","options":["$x + 2 = 59$","$x + (x - 2) = 59$","$x + (x + 2) = 59$","$x(x + 2) = 59$"],"correct":2,"why":"Pedro tiene $x + 2$ años; la suma de las edades es $x + (x + 2) = 59$."},{"q":"Pedro tiene 11 años más que Ana, y entre los dos suman 50 años. Si Ana tiene $x$ años, ¿qué ecuación representa esta situación?","options":["$x + (x - 11) = 50$","$x + 11 = 50$","$x(x + 11) = 50$","$x + (x + 11) = 50$"],"correct":3,"why":"Pedro tiene $x + 11$ años; la suma de las edades es $x + (x + 11) = 50$."},{"q":"Un taxi cobra CLP 1500 fijos más CLP 350 por kilómetro. Si un viaje costó CLP 6400 y se recorrieron $x$ km, ¿qué ecuación representa esta situación?","options":["$1850x = 6400$","$350 + 1500x = 6400$","$(1500 + 350)x = 6400$","$1500 + 350x = 6400$"],"correct":3,"why":"El costo fijo se suma una vez; el variable se multiplica por $x$: $1500 + 350x = 6400$."},{"q":"Un taxi cobra CLP 1500 fijos más CLP 350 por kilómetro. Si un viaje costó CLP 5000 y se recorrieron $x$ km, ¿qué ecuación representa esta situación?","options":["$(1500 + 350)x = 5000$","$350 + 1500x = 5000$","$1500 + 350x = 5000$","$1850x = 5000$"],"correct":2,"why":"El costo fijo se suma una vez; el variable se multiplica por $x$: $1500 + 350x = 5000$."},{"q":"Un número aumentado en 4 es igual al doble del mismo número disminuido en 8. ¿Qué ecuación representa esta situación?","options":["$x + 4 = 2(x - 8)$","$x + 4 = 2x - 8$","$x + 4 = 2(x + 8)$","$2(x + 4) = x - 8$"],"correct":0,"why":"«El doble del número disminuido en 8» es $2(x - 8)$, con paréntesis, porque se duplica el resultado de la resta."},{"q":"Un número aumentado en 3 es igual al doble del mismo número disminuido en 5. ¿Qué ecuación representa esta situación?","options":["$x + 3 = 2(x + 5)$","$x + 3 = 2(x - 5)$","$x + 3 = 2x - 5$","$2(x + 3) = x - 5$"],"correct":1,"why":"«El doble del número disminuido en 5» es $2(x - 5)$, con paréntesis, porque se duplica el resultado de la resta."},{"q":"Se reparten 43 fichas entre tres niños: el primero recibe $x$, el segundo recibe el doble que el primero y el tercero recibe 3 más que el primero. ¿Qué ecuación representa esta situación?","options":["$x + 2x + 3 = 43$","$x + 2 + (x + 3) = 43$","$x \\cdot 2x \\cdot (x + 3) = 43$","$x + 2x + (x + 3) = 43$"],"correct":3,"why":"Las partes son $x$, $2x$ y $x + 3$; el total es la suma: $x + 2x + (x + 3) = 43$."},{"q":"Se reparten 40 fichas entre tres niños: el primero recibe $x$, el segundo recibe el doble que el primero y el tercero recibe 4 más que el primero. ¿Qué ecuación representa esta situación?","options":["$x + 2 + (x + 4) = 40$","$x \\cdot 2x \\cdot (x + 4) = 40$","$x + 2x + (x + 4) = 40$","$x + 2x + 4 = 40$"],"correct":2,"why":"Las partes son $x$, $2x$ y $x + 4$; el total es la suma: $x + 2x + (x + 4) = 40$."}],"check":{"q":"Una muestra de agua está a $15\\,^\\circ\\mathrm{C}$ y se calienta a razón de $4\\,^\\circ\\mathrm{C}$ por minuto. Si $t$ es el tiempo en minutos, ¿qué ecuación permite calcular cuándo alcanza $55\\,^\\circ\\mathrm{C}$?","options":["$15 + 4t = 55$","$15t + 4 = 55$","$4 + 15t = 55$"],"correct":0,"why":"La temperatura inicial se suma al aumento de $4\\,^\\circ\\mathrm{C}$ por cada minuto transcurrido: $15 + 4t = 55$, de donde $t = 10$."},"draw":5,"checks":[{"q":"Se mezclan $x$ mL de agua con el triple de esa cantidad de ácido, y el volumen total es $52\\,\\mathrm{mL}$. ¿Qué ecuación representa esta situación?","options":["$3x = 52$","$x + 3 = 52$","$x + 3x = 52$","$x \\cdot 3x = 52$"],"correct":2,"why":"La mezcla total es la suma de las dos partes: $x + 3x = 52$."},{"q":"En un cultivo hay $x$ bacterias de tipo A y el triple de esa cantidad de tipo B; en total hay $52$. ¿Qué ecuación representa esta situación?","options":["$3x = 52$","$x \\cdot 3x = 52$","$x + 3x = 52$","$x + 3 = 52$"],"correct":2,"why":"La mezcla total es la suma de las dos partes: $x + 3x = 52$."},{"q":"Un ciclista parte a $10\\,\\mathrm{km}$ del inicio y avanza a $4\\,\\mathrm{km/h}$. Si $x$ son las horas de viaje, ¿qué ecuación permite saber cuándo estará a $22\\,\\mathrm{km}$ del inicio?","options":["$4 + x = 22$","$10 + 4x = 22$","$10 + 4 = 22x$","$14x = 22$"],"correct":1,"why":"La posición inicial se suma a lo que avanza en $x$ unidades de tiempo: $10 + 4x = 22$."},{"q":"Un dron está a $19\\,\\mathrm{m}$ de altura y sube $13\\,\\mathrm{m}$ por segundo. Si $x$ son los segundos, ¿qué ecuación permite saber cuándo estará a $71\\,\\mathrm{m}$?","options":["$19 + 13 = 71x$","$32x = 71$","$19 + 13x = 71$","$13 + x = 71$"],"correct":2,"why":"La posición inicial se suma a lo que avanza en $x$ unidades de tiempo: $19 + 13x = 71$."},{"q":"Una planta mide $24\\,\\mathrm{cm}$ y crece $6\\,\\mathrm{cm}$ por semana. Si $x$ son las semanas, ¿qué ecuación permite saber cuándo medirá $42\\,\\mathrm{cm}$?","options":["$24 + 6x = 42$","$6 + x = 42$","$30x = 42$","$24 + 6 = 42x$"],"correct":0,"why":"La posición inicial se suma a lo que avanza en $x$ unidades de tiempo: $24 + 6x = 42$."},{"q":"Un terreno rectangular de cultivo tiene un largo que mide $3\\,\\mathrm{m}$ más que su ancho $x$. Si su perímetro es $42\\,\\mathrm{m}$, ¿qué ecuación representa esta situación?","options":["$x(x + 3) = 42$","$2x + (x + 3) = 42$","$2x + 2(x + 3) = 42$","$x + (x + 3) = 42$"],"correct":2,"why":"El perímetro suma dos anchos y dos largos: $2x + 2(x + 3) = 42$."},{"q":"Una piscina experimental rectangular tiene un largo $2\\,\\mathrm{m}$ mayor que su ancho $x$ y un perímetro de $28\\,\\mathrm{m}$. ¿Qué ecuación representa esta situación?","options":["$x + (x + 2) = 28$","$x(x + 2) = 28$","$2x + 2(x + 2) = 28$","$2x + (x + 2) = 28$"],"correct":2,"why":"El perímetro suma dos anchos y dos largos: $2x + 2(x + 2) = 28$."},{"q":"Un fósil A tiene $6$ millones de años más que un fósil B. Entre ambos suman $48$ millones de años. Si B tiene $x$ millones de años, ¿qué ecuación representa esta situación?","options":["$x + (x - 6) = 48$","$x(x + 6) = 48$","$x + (x + 6) = 48$","$x + 6 = 48$"],"correct":2,"why":"El segundo fósil tiene $x + 6$ millones de años; la suma es $x + (x + 6) = 48$."},{"q":"Una roca A es $8$ millones de años más antigua que una roca B, y juntas suman $82$ millones de años. Si B tiene $x$ millones de años, ¿qué ecuación representa esta situación?","options":["$x + (x + 8) = 82$","$x + 8 = 82$","$x + (x - 8) = 82$","$x(x + 8) = 82$"],"correct":0,"why":"El segundo fósil tiene $x + 8$ millones de años; la suma es $x + (x + 8) = 82$."},{"q":"Un resorte de largo natural $15\\,\\mathrm{cm}$ tiene constante $7\\,\\mathrm{N/cm}$ y ejerce una fuerza de $21\\,\\mathrm{N}$. Si $x$ es su largo actual en cm, ¿qué ecuación representa esta situación?","options":["$7(x - 15) = 21$","$7(x + 15) = 21$","$7x - 15 = 21$","$x - 15 = 21$"],"correct":0,"why":"La fuerza es la constante por el alargamiento, que es el largo menos el largo natural: $7(x - 15) = 21$."},{"q":"Un resorte de largo natural $15\\,\\mathrm{cm}$ y constante $6\\,\\mathrm{N/cm}$ se estira hasta ejercer $12\\,\\mathrm{N}$. Si $x$ es su largo en cm, ¿qué ecuación representa esta situación?","options":["$6(x + 15) = 12$","$x - 15 = 12$","$6(x - 15) = 12$","$6x - 15 = 12$"],"correct":2,"why":"La fuerza es la constante por el alargamiento, que es el largo menos el largo natural: $6(x - 15) = 12$."},{"q":"Un robot A va a $15\\,\\mathrm{m/min}$ y alcanza a un robot B que va a $9\\,\\mathrm{m/min}$ y salió $29\\,\\mathrm{m}$ antes. Si $x$ son los minutos hasta que A alcanza a B, ¿qué ecuación representa esta situación?","options":["$15x = 9x - 29$","$15x + 9x = 29$","$15x = 9x + 29$","$6x = 30$"],"correct":2,"why":"El móvil rápido recorre $15x$; el lento recorre $9x$ más la ventaja de $29$: $15x = 9x + 29$."},{"q":"Una lancha rápida va a $13\\,\\mathrm{km/h}$ y persigue a otra que va a $7\\,\\mathrm{km/h}$ y lleva $31\\,\\mathrm{km}$ de ventaja. Si $x$ son las horas hasta alcanzarla, ¿qué ecuación representa esta situación?","options":["$13x + 7x = 31$","$6x = 32$","$13x = 7x - 31$","$13x = 7x + 31$"],"correct":3,"why":"El móvil rápido recorre $13x$; el lento recorre $7x$ más la ventaja de $31$: $13x = 7x + 31$."},{"q":"Un ciclista a $12\\,\\mathrm{m/s}$ persigue a otro a $5\\,\\mathrm{m/s}$ que tiene $18\\,\\mathrm{m}$ de ventaja. Si $x$ son los segundos hasta alcanzarlo, ¿qué ecuación representa esta situación?","options":["$12x + 5x = 18$","$7x = 19$","$12x = 5x + 18$","$12x = 5x - 18$"],"correct":2,"why":"El móvil rápido recorre $12x$; el lento recorre $5x$ más la ventaja de $18$: $12x = 5x + 18$."},{"q":"El número de bacterias de un cultivo aumentado en $32$ es igual al triple del número inicial $x$. ¿Qué ecuación representa esta situación?","options":["$x + 3 = 32x$","$x + 3x = 32$","$x + 32 = 3x$","$3(x + 32) = x$"],"correct":2,"why":"El número aumentado en 32, $x + 32$, es igual al triple, $3x$."},{"q":"La cantidad de moléculas de una muestra aumentada en $6$ es igual al triple de la cantidad inicial $x$. ¿Qué ecuación representa esta situación?","options":["$3(x + 6) = x$","$x + 3x = 6$","$x + 3 = 6x$","$x + 6 = 3x$"],"correct":3,"why":"El número aumentado en 6, $x + 6$, es igual al triple, $3x$."},{"q":"Un medicamento se administra a razón de $3\\,\\mathrm{mg}$ por kilogramo y a un paciente le corresponden $228\\,\\mathrm{mg}$ en total. Si $x$ es su masa en kg, ¿qué ecuación representa esta situación?","options":["$x + 3 = 228$","$3x = 228$","$\\dfrac{3}{x} = 228$","$3 - x = 228$"],"correct":1,"why":"La dosis total es la dosis por kg multiplicada por el peso $x$: $3x = 228$."},{"q":"Un fertilizante se aplica a razón de $7\\,\\mathrm{g}$ por metro cuadrado y se usan $532\\,\\mathrm{g}$ en total. Si $x$ es el área en $\\mathrm{m^2}$, ¿qué ecuación representa esta situación?","options":["$\\dfrac{7}{x} = 532$","$7 - x = 532$","$x + 7 = 532$","$7x = 532$"],"correct":3,"why":"La dosis total es la dosis por kg multiplicada por el peso $x$: $7x = 532$."},{"q":"Un reactor produce $12\\,\\mathrm{g}$ de producto por hora y produjo $372\\,\\mathrm{g}$ en total. Si $x$ son las horas de funcionamiento, ¿qué ecuación representa esta situación?","options":["$12 - x = 372$","$x + 12 = 372$","$12x = 372$","$\\dfrac{12}{x} = 372$"],"correct":2,"why":"La dosis total es la dosis por kg multiplicada por el peso $x$: $12x = 372$."}],"drawCheck":5,"unit":0},{"id":"u3-s006","title":"Resolver problemas lineales","subtitle":"Plantear, resolver y verificar","group":1,"symbol":"✧","minutes":50,"concept":"Un problema con ecuaciones se resuelve en cuatro pasos:\n1) Leer el enunciado y definir la incógnita.\n2) Plantear la ecuación.\n3) Resolverla.\n4) Verificar que la solución cumple el enunciado y que tiene sentido en el contexto (por ejemplo, una longitud no puede ser negativa).\n\nAl final, escribe la respuesta con sus unidades.","example":"Ana y Luis tienen 36 libros en total, y Ana tiene el triple que Luis. Si Luis tiene $x$ libros, Ana tiene $3x$:\n$$x + 3x = 36 \\quad\\Rightarrow\\quad 4x = 36 \\quad\\Rightarrow\\quad x = 9$$\nLuis tiene 9 libros y Ana tiene 27; en total son 36, así que la solución es correcta.","media":[],"practice":[{"type":"input","kind":"number","q":"Ana tiene el triple de libros que Luis y entre los dos tienen 36. ¿Cuántos libros tiene Luis?","answer":"9","why":"Si Luis tiene $x$ libros, Ana tiene $3x$: $x + 3x = 36$, luego $4x = 36$ y $x = 9$."},{"type":"input","kind":"number","q":"Un rectángulo tiene perímetro 30 cm y su largo mide 3 cm más que su ancho. ¿Cuánto mide el ancho? Escribe solo el número, en $\\mathrm{cm}$.","answer":"6","why":"Si el ancho es $x$, el largo es $x + 3$ y el perímetro es el doble de la suma de ambos: $2(x + x + 3) = 30$, luego $4x + 6 = 30$ y $x = 6$."},{"type":"input","kind":"number","q":"Sofía tiene cinco veces las figuritas que Pablo, y entre los dos tienen 54. ¿Cuántas figuritas tiene Pablo?","answer":"9","why":"Con $x$ las de Pablo: $x + 5x = 54$, luego $6x = 54$ y $x = 9$."},{"type":"input","kind":"number","q":"Sofía tiene cuatro veces las figuritas que Pablo, y entre los dos tienen 55. ¿Cuántas figuritas tiene Pablo?","answer":"11","why":"Con $x$ las de Pablo: $x + 4x = 55$, luego $5x = 55$ y $x = 11$."},{"type":"input","kind":"number","q":"Un rectángulo tiene perímetro 28 cm y su largo mide 6 cm más que su ancho. ¿Cuánto mide el ancho? Escribe solo el número, en $\\mathrm{cm}$.","answer":"4","why":"Con ancho $x$: $2x + 2(x + 6) = 28$, luego $4x = 16$ y $x = 4$."},{"type":"input","kind":"number","q":"Un rectángulo tiene perímetro 26 cm y su largo mide 7 cm más que su ancho. ¿Cuánto mide el ancho? Escribe solo el número, en $\\mathrm{cm}$.","answer":"3","why":"Con ancho $x$: $2x + 2(x + 7) = 26$, luego $4x = 12$ y $x = 3$."},{"type":"input","kind":"number","q":"La suma de tres números enteros consecutivos es 81. ¿Cuál es el menor?","answer":"26","why":"Con el menor $x$: $x + (x + 1) + (x + 2) = 81$, es decir $3x + 3 = 81$ y $x = 26$."},{"type":"input","kind":"number","q":"La suma de tres números enteros consecutivos es 66. ¿Cuál es el menor?","answer":"21","why":"Con el menor $x$: $x + (x + 1) + (x + 2) = 66$, es decir $3x + 3 = 66$ y $x = 21$."},{"q":"Un padre tiene 24 años más que su hijo y entre ambos suman 60 años. ¿Cuántos años tiene el hijo?","options":["$31$ años","$18$ años","$36$ años","$42$ años"],"correct":1,"why":"Con $x$ la edad del hijo: $x + (x + 24) = 60$, luego $2x = 36$ y $x = 18$."},{"q":"Un padre tiene 28 años más que su hijo y entre ambos suman 56 años. ¿Cuántos años tiene el hijo?","options":["$28$ años","$42$ años","$14$ años","$29$ años"],"correct":2,"why":"Con $x$ la edad del hijo: $x + (x + 28) = 56$, luego $2x = 28$ y $x = 14$."},{"q":"Un taxi cobra CLP 2000 fijos más CLP 500 por kilómetro. Si un viaje costó CLP 10500, ¿cuántos kilómetros se recorrieron?","options":["$18$ km","$17$ km","$21$ km","$8500$ km"],"correct":1,"why":"Con $x$ km: $2000 + 500x = 10500$, luego $500x = 8500$ y $x = 17$."},{"q":"Un taxi cobra CLP 2500 fijos más CLP 600 por kilómetro. Si un viaje costó CLP 7900, ¿cuántos kilómetros se recorrieron?","options":["$13$ km","$10$ km","$9$ km","$5400$ km"],"correct":2,"why":"Con $x$ km: $2500 + 600x = 7900$, luego $600x = 5400$ y $x = 9$."},{"q":"Si a 2 veces un número se le resta 7, se obtiene 17. ¿Cuál es el número?","options":["10","31","24","12"],"correct":3,"why":"Con $x$ el número: $2x - 7 = 17$, luego $2x = 24$ y $x = 12$."},{"q":"Si a 6 veces un número se le resta 5, se obtiene 67. ¿Cuál es el número?","options":["72","62","77","12"],"correct":3,"why":"Con $x$ el número: $6x - 5 = 67$, luego $6x = 72$ y $x = 12$."},{"q":"Sofía ya tiene CLP 5000 ahorrados y ahorra CLP 2000 cada semana. ¿En cuántas semanas tendrá CLP 25000?","options":["$12$ semanas","$9$ semanas","$10$ semanas","$11$ semanas"],"correct":2,"why":"Con $x$ semanas: $5000 + 2000x = 25000$, luego $2000x = 20000$ y $x = 10$."},{"q":"Sofía ya tiene CLP 8000 ahorrados y ahorra CLP 4000 cada semana. ¿En cuántas semanas tendrá CLP 24000?","options":["$5$ semanas","$3$ semanas","$4$ semanas","$6$ semanas"],"correct":2,"why":"Con $x$ semanas: $8000 + 4000x = 24000$, luego $4000x = 16000$ y $x = 4$."},{"q":"En un curso hay 30 estudiantes y hay 8 mujeres más que hombres. ¿Cuántos hombres hay?","options":["22","11","19","16"],"correct":1,"why":"Con $x$ hombres: $x + (x + 8) = 30$, luego $2x = 22$ y $x = 11$."},{"q":"En un curso hay 27 estudiantes y hay 3 mujeres más que hombres. ¿Cuántos hombres hay?","options":["15","24","14","12"],"correct":3,"why":"Con $x$ hombres: $x + (x + 3) = 27$, luego $2x = 24$ y $x = 12$."},{"q":"Un ciclista parte a 7 km del inicio de una ruta y avanza a 8 km/h. ¿En cuántas horas estará a 55 km del inicio?","options":["$6$ h","$48$ h","$5$ h","$7$ h"],"correct":0,"why":"Con $x$ horas: $7 + 8x = 55$, luego $8x = 48$ y $x = 6$."},{"q":"Un ciclista parte a 10 km del inicio de una ruta y avanza a 5 km/h. ¿En cuántas horas estará a 20 km del inicio?","options":["$3$ h","$10$ h","$4$ h","$2$ h"],"correct":3,"why":"Con $x$ horas: $10 + 5x = 20$, luego $5x = 10$ y $x = 2$."}],"check":{"q":"Dos robots parten del mismo punto de un laboratorio y se mueven en sentidos opuestos, uno a $12\\,\\mathrm{km/h}$ y el otro a $8\\,\\mathrm{km/h}$. ¿Cuánto tiempo debe pasar para que estén separados por $40\\,\\mathrm{km}$?","options":["$1\\,\\mathrm{h}$","$2\\,\\mathrm{h}$","$4\\,\\mathrm{h}$"],"correct":1,"why":"La distancia entre ellos aumenta a razón de $12 + 8$ km por hora: $12t + 8t = 40$, luego $20t = 40$ y $t = 2$."},"draw":5,"checks":[{"type":"input","kind":"number","q":"Se mezclan agua y ácido de modo que hay el doble de ácido que de agua. El volumen total es $33\\,\\mathrm{mL}$. ¿Cuántos mL de agua hay? Escribe solo el número, en $\\mathrm{mL}$.","answer":"11","why":"Con $x$ la cantidad menor: $x + 2x = 33$, luego $3x = 33$ y $x = 11$."},{"q":"Una aleación contiene el triple de cobre que de estaño y tiene una masa total de $60\\,\\mathrm{g}$. ¿Cuántos gramos de estaño contiene?","options":["$20\\,\\mathrm{g}$","$15\\,\\mathrm{g}$","$45\\,\\mathrm{g}$","$57\\,\\mathrm{g}$"],"correct":1,"why":"Con $x$ la cantidad menor: $x + 3x = 60$, luego $4x = 60$ y $x = 15$."},{"type":"input","kind":"number","q":"Un robot A va a $8\\,\\mathrm{m/min}$ y persigue a un robot B que va a $2\\,\\mathrm{m/min}$ y salió $18\\,\\mathrm{m}$ antes. ¿Cuántos minutos tarda A en alcanzar a B? Escribe solo el número, en $\\mathrm{min}$.","answer":"3","why":"Igualamos: $8t = 2t + 18$, luego $6t = 18$ y $t = 3$."},{"q":"Una lancha va a $7\\,\\mathrm{km/h}$ y persigue a otra que va a $3\\,\\mathrm{km/h}$ y lleva $16\\,\\mathrm{km}$ de ventaja. ¿En cuántas horas la alcanza?","options":["$16\\,\\mathrm{h}$","$\\dfrac{16}{7}\\,\\mathrm{h}$","$\\dfrac{8}{5}\\,\\mathrm{h}$","$4\\,\\mathrm{h}$"],"correct":3,"why":"Igualamos: $7t = 3t + 16$, luego $4t = 16$ y $t = 4$."},{"type":"input","kind":"number","q":"Una muestra está a $17\\,^\\circ\\mathrm{C}$ y se calienta a razón de $5\\,^\\circ\\mathrm{C}$ por minuto. ¿En cuántos minutos llegará a $72\\,^\\circ\\mathrm{C}$? Escribe solo el número, en $\\mathrm{min}$.","answer":"11","why":"Planteamos $17 + 5t = 72$; entonces $5t = 55$ y $t = 11$."},{"q":"Un líquido está a $20\\,^\\circ\\mathrm{C}$ y un calefactor lo sube $7\\,^\\circ\\mathrm{C}$ cada minuto. ¿En cuántos minutos alcanzará $76\\,^\\circ\\mathrm{C}$?","options":["$8\\,\\mathrm{min}$","$56\\,\\mathrm{min}$","$63\\,\\mathrm{min}$","$\\dfrac{76}{7}\\,\\mathrm{min}$"],"correct":0,"why":"Planteamos $20 + 7t = 76$; entonces $7t = 56$ y $t = 8$."},{"type":"input","kind":"number","q":"Un medicamento se da a razón de $2\\,\\mathrm{mg}$ por kilogramo y a un paciente le corresponden $134\\,\\mathrm{mg}$ en total. ¿Cuánto pesa el paciente? Escribe solo el número, en $\\mathrm{kg}$.","answer":"67","why":"Planteamos $2x = 134$; dividimos por 2 y obtenemos $x = 67$."},{"q":"Un fósil A tiene $11$ millones de años más que un fósil B, y entre los dos suman $43$ millones de años. ¿Cuántos millones de años tiene B?","options":["$32$","$16$","$27$","$\\dfrac{43}{2}$"],"correct":1,"why":"Con $x$ la edad menor: $x + (x + 11) = 43$, luego $2x = 32$ y $x = 16$."},{"type":"input","kind":"number","q":"Una roca A tiene $6$ millones de años más que una roca B, y entre las dos suman $56$ millones de años. ¿Cuántos millones de años tiene B?","answer":"25","why":"Con $x$ la edad menor: $x + (x + 6) = 56$, luego $2x = 50$ y $x = 25$."},{"q":"Un tanque contiene $29\\,\\mathrm{L}$ y se llena a $8\\,\\mathrm{L}$ por minuto. ¿Cuántos minutos tarda en tener $109\\,\\mathrm{L}$?","options":["$80\\,\\mathrm{min}$","$10\\,\\mathrm{min}$","$\\dfrac{109}{8}\\,\\mathrm{min}$","$11\\,\\mathrm{min}$"],"correct":1,"why":"Planteamos $29 + 8t = 109$; luego $8t = 80$ y $t = 10$."},{"type":"input","kind":"number","q":"Un cultivo tiene $24$ miles de células y crece en $5$ miles por hora. ¿Cuántas horas pasan hasta que tenga $74$ miles? Escribe solo el número, en $\\mathrm{h}$.","answer":"10","why":"Planteamos $24 + 5t = 74$; luego $5t = 50$ y $t = 10$."},{"q":"Un metal tiene densidad de $4\\,\\mathrm{g/cm^3}$ y una pieza tiene una masa de $100\\,\\mathrm{g}$. ¿Cuál es su volumen?","options":["$25\\,\\mathrm{cm^3}$","$104\\,\\mathrm{cm^3}$","$96\\,\\mathrm{cm^3}$","$400\\,\\mathrm{cm^3}$"],"correct":0,"why":"Planteamos $4V = 100$ y dividimos por 4: $V = 25$."},{"type":"input","kind":"number","q":"Un mineral tiene densidad de $4\\,\\mathrm{g/cm^3}$ y una muestra pesa $28\\,\\mathrm{g}$. ¿Qué volumen ocupa? Escribe solo el número, en $\\mathrm{cm^3}$.","answer":"7","why":"Planteamos $4V = 28$ y dividimos por 4: $V = 7$."},{"q":"El sonido viaja en el aire a unos $340\\,\\mathrm{m/s}$. Una tormenta está a $2720\\,\\mathrm{m}$. ¿Cuántos segundos tarda en llegar el trueno?","options":["$8\\,\\mathrm{s}$","$2380\\,\\mathrm{s}$","$10\\,\\mathrm{s}$","$9\\,\\mathrm{s}$"],"correct":0,"why":"Planteamos $340t = 2720$; dividimos por 340 y obtenemos $t = 8$."},{"type":"input","kind":"number","q":"Un sonar emite un pulso que viaja a $340\\,\\mathrm{m/s}$ hasta un obstáculo ubicado a $1700\\,\\mathrm{m}$. ¿Cuántos segundos tarda el pulso en llegar al obstáculo (solo la ida)? Escribe solo el número, en $\\mathrm{s}$.","answer":"5","why":"Planteamos $340t = 1700$; dividimos por 340 y obtenemos $t = 5$."},{"q":"La temperatura media de $4$ mediciones fue $22\\,^\\circ\\mathrm{C}$. Las primeras fueron $24, 25, 23$ (en $^\\circ\\mathrm{C}$). ¿Cuánto marcó la última medición?","options":["$20\\,^\\circ\\mathrm{C}$","$22\\,^\\circ\\mathrm{C}$","$16\\,^\\circ\\mathrm{C}$","$88\\,^\\circ\\mathrm{C}$"],"correct":2,"why":"Si la media es 22, la suma debe ser 88. Falta 88 - 72 = 16."},{"q":"En $5$ días la temperatura media de un invernadero fue $18\\,^\\circ\\mathrm{C}$. Los primeros días registraron $19, 15, 18, 19$ (en $^\\circ\\mathrm{C}$). ¿Qué temperatura registró el último día?","options":["$19\\,^\\circ\\mathrm{C}$","$24\\,^\\circ\\mathrm{C}$","$90\\,^\\circ\\mathrm{C}$","$18\\,^\\circ\\mathrm{C}$"],"correct":0,"why":"Si la media es 18, la suma debe ser 90. Falta 90 - 71 = 19."},{"q":"La relación entre grados Celsius y Fahrenheit es $F = \\dfrac{9}{5}C + 32$. Un termómetro marca $95\\,^\\circ\\mathrm{F}$. ¿Cuántos grados Celsius son?","options":["$35\\,^\\circ\\mathrm{C}$","$63\\,^\\circ\\mathrm{C}$","$40\\,^\\circ\\mathrm{C}$","$\\dfrac{567}{5}\\,^\\circ\\mathrm{C}$"],"correct":0,"why":"De $F = \\frac{9}{5}C + 32$: $95 - 32 = \\frac{9}{5}C$, luego $C = 35$."},{"q":"Un horno marca $59\\,^\\circ\\mathrm{F}$. Sabiendo que $F = \\dfrac{9}{5}C + 32$, ¿cuántos grados Celsius son?","options":["$20\\,^\\circ\\mathrm{C}$","$\\dfrac{243}{5}\\,^\\circ\\mathrm{C}$","$15\\,^\\circ\\mathrm{C}$","$27\\,^\\circ\\mathrm{C}$"],"correct":2,"why":"De $F = \\frac{9}{5}C + 32$: $59 - 32 = \\frac{9}{5}C$, luego $C = 15$."}],"drawCheck":5,"unit":0},{"id":"u3-s007","title":"Cuadráticas incompletas","subtitle":"Sin término lineal o sin constante","group":2,"symbol":"✧","minutes":40,"concept":"Una ecuación cuadrática tiene la forma $ax^2 + bx + c = 0$ con $a \\neq 0$. Es incompleta cuando le falta el término $bx$ o el término $c$.\n\nSi falta $bx$, se despeja $x^2$ y se aplica raíz cuadrada considerando las dos raíces: si $x^2 = k$ con $k > 0$, entonces $x = \\pm\\sqrt{k}$.\n\nSi falta $c$, se saca $x$ como factor común: $x(ax + b) = 0$. Como un producto es cero cuando alguno de sus factores es cero, las soluciones son $x = 0$ y $x = -\\frac{b}{a}$.","example":"Resolvemos $x^2 - 5x = 0$. Sacamos factor común:\n$$x(x - 5) = 0 \\quad\\Rightarrow\\quad x = 0 \\ \\text{ o } \\ x = 5$$\nResolvemos $x^2 - 49 = 0$: despejamos $x^2 = 49$, luego $x = \\pm 7$.","media":[],"practice":[{"type":"input","kind":"set","q":"Resuelve la ecuación:\n$$x^2 - 49 = 0$$\n\nEscribe todas las soluciones.","answer":"7; -7","why":"Despejamos $x^2$ y consideramos las dos raíces cuadradas, la positiva y la negativa: $x^2 = 49$, luego $x = \\pm 7$."},{"q":"Resuelve la ecuación:\n$$x^2 - 5x = 0$$","options":["$x = 0$ y $x = 5$","$x = 5$ únicamente","$x = 0$ y $x = -5$"],"correct":0,"why":"Sacamos $x$ como factor común y usamos que un producto es cero cuando alguno de sus factores es cero: $x(x - 5) = 0$, luego $x = 0$ o $x = 5$."},{"type":"input","kind":"set","q":"Resuelve la ecuación:\n$$x^2 - 4 = 0$$\n\nEscribe todas las soluciones.","answer":"-2; 2","why":"Pasamos 4 al otro lado: $x^2 = 4$, así que $x = \\pm 2$."},{"q":"Resuelve la ecuación:\n$$x^2 - 144 = 0$$","options":["$x=-12$","$x=-144$ y $x=144$","$x=-12$ y $x=12$","$x=12$"],"correct":2,"why":"Pasamos 144 al otro lado: $x^2 = 144$, así que $x = \\pm 12$."},{"type":"input","kind":"set","q":"Resuelve la ecuación:\n$$x^2 - 64 = 0$$\n\nEscribe todas las soluciones.","answer":"-8; 8","why":"Pasamos 64 al otro lado: $x^2 = 64$, así que $x = \\pm 8$."},{"q":"Resuelve la ecuación:\n$$4x^2 = 16$$","options":["$x=-4$ y $x=4$","$x=2$","$x=-2$ y $x=2$","$x=-12$ y $x=12$"],"correct":2,"why":"Dividimos por 4: $x^2 = 4$, luego $x = \\pm 2$."},{"type":"input","kind":"set","q":"Resuelve la ecuación:\n$$2x^2 = 32$$\n\nEscribe todas las soluciones.","answer":"-4; 4","why":"Dividimos por 2: $x^2 = 16$, luego $x = \\pm 4$."},{"q":"Resuelve la ecuación:\n$$8x^2 = 200$$","options":["$x=-5$ y $x=5$","$x=-192$ y $x=192$","$x=-25$ y $x=25$","$x=5$"],"correct":0,"why":"Dividimos por 8: $x^2 = 25$, luego $x = \\pm 5$."},{"q":"¿Cuántas soluciones reales tiene la ecuación $x^2 + 16 = 0$?","options":["Una","Ninguna","Dos","Infinitas"],"correct":1,"why":"De $x^2 = -16$: un cuadrado nunca es negativo, por eso no hay soluciones reales."},{"q":"¿Cuántas soluciones reales tiene la ecuación $x^2 + 4 = 0$?","options":["Dos","Una","Infinitas","Ninguna"],"correct":3,"why":"De $x^2 = -4$: un cuadrado nunca es negativo, por eso no hay soluciones reales."},{"type":"input","kind":"set","q":"Resuelve la ecuación:\n$$x^2 - 9x = 0$$\n\nEscribe todas las soluciones.","answer":"0; 9","why":"Factorizamos: $x(x - 9) = 0$. Entonces $x = 0$ o $x = 9$."},{"q":"Resuelve la ecuación:\n$$x^2 - 3x = 0$$","options":["$x=0$ y $x=3$","$x=3$","$x=-3$ y $x=3$","$x=-3$ y $x=0$"],"correct":0,"why":"Factorizamos: $x(x - 3) = 0$. Entonces $x = 0$ o $x = 3$."},{"type":"input","kind":"set","q":"Resuelve la ecuación:\n$$x^2 - 10x = 0$$\n\nEscribe todas las soluciones.","answer":"0; 10","why":"Factorizamos: $x(x - 10) = 0$. Entonces $x = 0$ o $x = 10$."},{"q":"Resuelve la ecuación:\n$$3x^2 + 18x = 0$$","options":["$x=0$ y $x=6$","$x=-18$ y $x=0$","$x=-6$ y $x=0$","$x=-6$"],"correct":2,"why":"Factorizamos: $x(3x + 18) = 0$. Entonces $x = 0$ o $x = -6$."},{"type":"input","kind":"set","q":"Resuelve la ecuación:\n$$5x^2 - 30x = 0$$\n\nEscribe todas las soluciones.","answer":"0; 6","why":"Factorizamos: $x(5x - 30) = 0$. Entonces $x = 0$ o $x = 6$."},{"q":"Resuelve la ecuación:\n$$5x^2 + 10x = 0$$","options":["$x=-2$","$x=-10$ y $x=0$","$x=0$ y $x=2$","$x=-2$ y $x=0$"],"correct":3,"why":"Factorizamos: $x(5x + 10) = 0$. Entonces $x = 0$ o $x = -2$."},{"type":"input","kind":"set","q":"Resuelve la ecuación:\n$$(x + 2)^2 = 9$$\n\nEscribe todas las soluciones.","answer":"-5; 1","why":"Aplicamos raíz a ambos lados: $x + 2 = \\pm 3$, así que $x = -5$ o $x = 1$."},{"q":"Resuelve la ecuación:\n$$(x + 6)^2 = 16$$","options":["$x=-2$","$x=-4$ y $x=4$","$x=2$ y $x=10$","$x=-10$ y $x=-2$"],"correct":3,"why":"Aplicamos raíz a ambos lados: $x + 6 = \\pm 4$, así que $x = -10$ o $x = -2$."},{"q":"¿Qué se puede afirmar de la ecuación $x^2 = -8$ en los números reales?","options":["Tiene una solución: $x = -8$","Tiene dos soluciones: $x = 8$ y $x = -8$","Tiene infinitas soluciones","No tiene solución, porque un cuadrado no puede ser negativo"],"correct":3,"why":"Todo número real al cuadrado es mayor o igual que cero, así que no puede ser igual a un número negativo."},{"q":"¿Cuántas soluciones reales tiene la ecuación $3x^2 = 0$?","options":["Dos: $x = 0$ y $x = 3$","Ninguna","Dos: $x = 3$ y $x = -3$","Una: $x = 0$"],"correct":3,"why":"Dividimos por 3: $x^2 = 0$, y el único número cuyo cuadrado es 0 es el 0."}],"check":{"type":"input","kind":"number","q":"Un parche de cultivo de forma cuadrada tiene un área de $64\\,\\mathrm{cm}^2$. Si $x$ es la medida del lado en cm, se cumple $x^2 = 64$. ¿Cuánto mide el lado del parche? Escribe solo el número, en $\\mathrm{cm}$.","answer":"8","why":"La ecuación tiene dos soluciones, $x = \\pm 8$, pero una longitud no puede ser negativa; por eso $x = 8$."},"draw":5,"checks":[{"q":"Un objeto cae desde el reposo y su altura recorrida cumple $h = 5t^2$ (en metros, con $t$ en segundos). ¿Cuántos segundos tarda en caer $80\\,\\mathrm{m}$?","options":["$4\\,\\mathrm{s}$","$20\\,\\mathrm{s}$","$80\\,\\mathrm{s}$","$16\\,\\mathrm{s}$"],"correct":0,"why":"Resolvemos $5t^2 = 80$: $t^2 = 16$, luego $t = \\pm 4$. El tiempo no puede ser negativo, así que $t = 4$."},{"type":"input","kind":"number","q":"Una piedra se suelta desde un acantilado y cae $h = 5t^2$ metros en $t$ segundos. ¿Cuánto tarda en recorrer $80\\,\\mathrm{m}$? Escribe solo el número, en $\\mathrm{s}$.","answer":"4","why":"Resolvemos $5t^2 = 80$: $t^2 = 16$, luego $t = \\pm 4$. El tiempo no puede ser negativo, así que $t = 4$."},{"q":"Un fruto se desprende de un árbol y recorre $h = 5t^2$ metros en $t$ segundos. ¿Cuánto tarda en caer $20\\,\\mathrm{m}$?","options":["$2\\,\\mathrm{s}$","$4\\,\\mathrm{s}$","$20\\,\\mathrm{s}$","$10\\,\\mathrm{s}$"],"correct":0,"why":"Resolvemos $5t^2 = 20$: $t^2 = 4$, luego $t = \\pm 2$. El tiempo no puede ser negativo, así que $t = 2$."},{"type":"input","kind":"number","q":"Un paracaidista inicia la caída libre y, en los primeros instantes, recorre $h = 5t^2$ metros. ¿Cuántos segundos tarda en recorrer $405\\,\\mathrm{m}$? Escribe solo el número, en $\\mathrm{s}$.","answer":"9","why":"Resolvemos $5t^2 = 405$: $t^2 = 81$, luego $t = \\pm 9$. El tiempo no puede ser negativo, así que $t = 9$."},{"q":"Una gota se desprende de un techo y cae $h = 5t^2$ metros en $t$ segundos. ¿Cuánto tarda en caer $125\\,\\mathrm{m}$?","options":["$6\\,\\mathrm{s}$","$5\\,\\mathrm{s}$","$25\\,\\mathrm{s}$","$125\\,\\mathrm{s}$"],"correct":1,"why":"Resolvemos $5t^2 = 125$: $t^2 = 25$, luego $t = \\pm 5$. El tiempo no puede ser negativo, así que $t = 5$."},{"type":"input","kind":"number","q":"Un cultivo cuadrado tiene un área de $81\\,\\mathrm{m^2}$. ¿Cuánto mide su lado? Escribe solo el número, en $\\mathrm{m}$.","answer":"9","why":"El área de un cuadrado es $x^2 = 81$, luego $x = 9$ (se descarta $-9$)."},{"q":"Una placa cuadrada de laboratorio tiene un área de $289\\,\\mathrm{cm^2}$. ¿Cuánto mide su lado?","options":["$34\\,\\mathrm{cm}$","$17\\,\\mathrm{cm}$","$\\dfrac{289}{2}\\,\\mathrm{cm}$","$289\\,\\mathrm{cm}$"],"correct":1,"why":"El área de un cuadrado es $x^2 = 289$, luego $x = 17$ (se descarta $-17$)."},{"type":"input","kind":"number","q":"La energía cinética es $E = \\dfrac{1}{2}mv^2$. Una partícula de $2\\,\\mathrm{kg}$ tiene $E = 144\\,\\mathrm{J}$. ¿Cuál es su rapidez en $\\mathrm{m/s}$? Escribe solo el número, en $\\mathrm{m/s}$.","answer":"12","why":"Con $m = 2\\,\\mathrm{kg}$: $\\frac{1}{2}\\cdot 2 \\cdot v^2 = v^2 = 144$, luego $v = 12$ (la velocidad se toma positiva)."},{"q":"Un carrito de laboratorio de $2\\,\\mathrm{kg}$ tiene una energía cinética $E = \\dfrac{1}{2}mv^2 = 64\\,\\mathrm{J}$. ¿Cuál es su rapidez en $\\mathrm{m/s}$?","options":["$10\\,\\mathrm{m/s}$","$8\\,\\mathrm{m/s}$","$64\\,\\mathrm{m/s}$","$32\\,\\mathrm{m/s}$"],"correct":1,"why":"Con $m = 2\\,\\mathrm{kg}$: $\\frac{1}{2}\\cdot 2 \\cdot v^2 = v^2 = 64$, luego $v = 8$ (la velocidad se toma positiva)."},{"type":"input","kind":"number","q":"Un balín de $2\\,\\mathrm{kg}$ posee $E = \\dfrac{1}{2}mv^2 = 100\\,\\mathrm{J}$. ¿Qué rapidez lleva en $\\mathrm{m/s}$? Escribe solo el número, en $\\mathrm{m/s}$.","answer":"10","why":"Con $m = 2\\,\\mathrm{kg}$: $\\frac{1}{2}\\cdot 2 \\cdot v^2 = v^2 = 100$, luego $v = 10$ (la velocidad se toma positiva)."},{"q":"La altura de una pelota lanzada hacia arriba es $h = -5t^2 + 30t$ (en metros, $t$ en segundos). ¿En qué instante $t > 0$ vuelve al suelo?","options":["$6\\,\\mathrm{s}$","$30\\,\\mathrm{s}$","$0\\,\\mathrm{s}$","$3\\,\\mathrm{s}$"],"correct":0,"why":"Resolvemos $-5t^2 + 30t = 0$: $-5t(t - 6) = 0$, así que $t = 0$ (lanzamiento) o $t = 6$ s."},{"type":"input","kind":"number","q":"Un cohete de agua sigue la trayectoria $h = -5t^2 + 10t$ (en metros). ¿Después de cuántos segundos vuelve al suelo? Escribe solo el número, en $\\mathrm{s}$.","answer":"2","why":"Resolvemos $-5t^2 + 10t = 0$: $-5t(t - 2) = 0$, así que $t = 0$ (lanzamiento) o $t = 2$ s."},{"q":"Una piedra lanzada verticalmente alcanza una altura $h = -5t^2 + 25t$. ¿Cuántos segundos tarda en volver al punto de lanzamiento?","options":["$5\\,\\mathrm{s}$","$\\dfrac{5}{2}\\,\\mathrm{s}$","$25\\,\\mathrm{s}$","$0\\,\\mathrm{s}$"],"correct":0,"why":"Resolvemos $-5t^2 + 25t = 0$: $-5t(t - 5) = 0$, así que $t = 0$ (lanzamiento) o $t = 5$ s."},{"type":"input","kind":"number","q":"La energía almacenada en un resorte es $E = 4x^2$ (en joules, con $x$ en metros). Si $E = 256\\,\\mathrm{J}$, ¿cuánto vale el estiramiento $x$? Escribe solo el número, en $\\mathrm{m}$.","answer":"8","why":"Dividimos por 4: $x^2 = 64$, luego $x = 8$ (longitud positiva)."},{"q":"Un amortiguador almacena una energía $E = 4x^2$ J al comprimirse $x$ metros. Si $E = 324\\,\\mathrm{J}$, ¿cuál es la compresión $x$?","options":["$324\\,\\mathrm{m}$","$36\\,\\mathrm{m}$","$9\\,\\mathrm{m}$","$81\\,\\mathrm{m}$"],"correct":2,"why":"Dividimos por 4: $x^2 = 81$, luego $x = 9$ (longitud positiva)."},{"q":"Una escalera de $25\\,\\mathrm{m}$ se apoya en una pared con su base a $7\\,\\mathrm{m}$ del muro. La altura $x$ que alcanza cumple $x^2 + 7^2 = 25^2$. ¿Cuánto vale $x$?","options":["$18\\,\\mathrm{m}$","$32\\,\\mathrm{m}$","$24\\,\\mathrm{m}$","$25\\,\\mathrm{m}$"],"correct":2,"why":"Por Pitágoras: $x^2 + 7^2 = 25^2$, luego $x^2 = 576$ y $x = 24$."},{"q":"Un cable de $25\\,\\mathrm{m}$ sujeta un mástil y se ancla a $7\\,\\mathrm{m}$ de su base. La altura $x$ de amarre cumple $x^2 + 7^2 = 25^2$. ¿Cuánto vale $x$?","options":["$18\\,\\mathrm{m}$","$24\\,\\mathrm{m}$","$32\\,\\mathrm{m}$","$25\\,\\mathrm{m}$"],"correct":1,"why":"Por Pitágoras: $x^2 + 7^2 = 25^2$, luego $x^2 = 576$ y $x = 24$."},{"q":"Un modelo para una longitud $x$ (en metros) llevó a la ecuación $x^2 = -14$. ¿Qué se concluye?","options":["Hay dos soluciones: $x = 14$ y $x = -14$","Hay una solución: $x = -14$","Hay infinitas soluciones","No existe solución real: un cuadrado no puede ser negativo"],"correct":3,"why":"$x^2 = -14$ no tiene solución en los números reales."},{"q":"Al modelar el lado $x$ de una celda se obtuvo $x^2 = -28$. ¿Qué se concluye en los números reales?","options":["No existe solución real: un cuadrado no puede ser negativo","Hay una solución: $x = -28$","Hay infinitas soluciones","Hay dos soluciones: $x = 28$ y $x = -28$"],"correct":0,"why":"$x^2 = -28$ no tiene solución en los números reales."}],"drawCheck":5,"unit":0},{"id":"u3-s008","title":"Cuadráticas por factorización","subtitle":"Producto igual a cero","group":2,"symbol":"✧","minutes":40,"concept":"Cuando la ecuación cuadrática se puede factorizar, se escribe como un producto igual a cero y se usa esta propiedad: si $A \\cdot B = 0$, entonces $A = 0$ o $B = 0$.\n\nPara factorizar un trinomio $x^2 + bx + c$, como en la Unidad 2, se buscan dos números que multiplicados den $c$ y sumados den $b$.\n\nSi el problema trata de una longitud, se descartan las soluciones negativas.","example":"Resolvemos $x^2 - 5x + 6 = 0$. Buscamos dos números que multiplicados den 6 y sumados den $-5$: son $-2$ y $-3$.\n$$(x - 2)(x - 3) = 0 \\quad\\Rightarrow\\quad x = 2 \\ \\text{ o } \\ x = 3$$\nVerificamos con $x = 2$: $2^2 - 5\\cdot 2 + 6 = 4 - 10 + 6 = 0$.","media":[],"practice":[{"type":"input","kind":"set","q":"Resuelve la ecuación:\n$$x^2 - 5x + 6 = 0$$\n\nEscribe todas las soluciones.","answer":"2; 3","why":"Buscamos dos números que multiplicados den $6$ y sumados den $-5$, que son $-2$ y $-3$: $(x - 2)(x - 3) = 0$, luego $x = 2$ o $x = 3$."},{"q":"Resuelve la ecuación:\n$$x^2 + 2x - 15 = 0$$","options":["$x = -5$ y $x = 3$","$x = 5$ y $x = -3$","$x = -5$ y $x = -3$"],"correct":0,"why":"Buscamos dos números que multiplicados den $-15$ y sumados den $2$, que son $5$ y $-3$: $(x + 5)(x - 3) = 0$, luego $x = -5$ o $x = 3$."},{"type":"input","kind":"set","q":"Resuelve la ecuación:\n$$x^2 + 12x + 32 = 0$$\n\nEscribe todas las soluciones.","answer":"-8; -4","why":"Buscamos dos números que multipliquen 32 y sumen 12: son 8 y 4. Entonces $(x + 8)(x + 4) = 0$."},{"q":"Resuelve la ecuación:\n$$x^2 - 5x - 14 = 0$$","options":["$x=-7$ y $x=-2$","$x=-2$ y $x=7$","$x=2$ y $x=7$","$x=-7$ y $x=2$"],"correct":1,"why":"Buscamos dos números que multipliquen -14 y sumen -5: son 2 y -7. Entonces $(x + 2)(x - 7) = 0$."},{"type":"input","kind":"set","q":"Resuelve la ecuación:\n$$x^2 - 14x + 45 = 0$$\n\nEscribe todas las soluciones.","answer":"5; 9","why":"Buscamos dos números que multipliquen 45 y sumen -14: son -5 y -9. Entonces $(x - 5)(x - 9) = 0$."},{"q":"Resuelve la ecuación:\n$$x^2 + 4x - 32 = 0$$","options":["$x=-8$ y $x=4$","$x=4$ y $x=8$","$x=-4$ y $x=8$","$x=-8$ y $x=-4$"],"correct":0,"why":"Buscamos dos números que multipliquen -32 y sumen 4: son 8 y -4. Entonces $(x + 8)(x - 4) = 0$."},{"type":"input","kind":"set","q":"Resuelve la ecuación:\n$$x^2 + 14x + 48 = 0$$\n\nEscribe todas las soluciones.","answer":"-8; -6","why":"Buscamos dos números que multipliquen 48 y sumen 14: son 6 y 8. Entonces $(x + 6)(x + 8) = 0$."},{"q":"Resuelve la ecuación:\n$$x^2 + 11x + 18 = 0$$","options":["$x=2$ y $x=9$","$x=-2$ y $x=9$","$x=-9$ y $x=-2$","$x=-9$ y $x=2$"],"correct":2,"why":"Buscamos dos números que multipliquen 18 y sumen 11: son 2 y 9. Entonces $(x + 2)(x + 9) = 0$."},{"type":"input","kind":"set","q":"Resuelve la ecuación:\n$$x^2 = -9x - 14$$\n\nEscribe todas las soluciones.","answer":"-7; -2","why":"Pasamos todo al lado izquierdo para igualar a cero y factorizamos; las soluciones son $-7$ y $-2$."},{"q":"Resuelve la ecuación:\n$$x^2 = -x + 30$$","options":["$x=-5$ y $x=6$","$x=5$ y $x=6$","$x=-6$ y $x=-5$","$x=-6$ y $x=5$"],"correct":3,"why":"Pasamos todo al lado izquierdo para igualar a cero y factorizamos; las soluciones son $-6$ y $5$."},{"type":"input","kind":"set","q":"Resuelve la ecuación:\n$$x^2 = -9x - 8$$\n\nEscribe todas las soluciones.","answer":"-8; -1","why":"Pasamos todo al lado izquierdo para igualar a cero y factorizamos; las soluciones son $-8$ y $-1$."},{"q":"Resuelve la ecuación:\n$$3x^2 + 14x - 5 = 0$$","options":["$x=\\dfrac{1}{3}$ y $x=5$","$x=-\\dfrac{1}{3}$ y $x=5$","$x=-5$ y $x=\\dfrac{1}{3}$","$x=-5$ y $x=-\\dfrac{1}{3}$"],"correct":2,"why":"Factorizamos: $(3x - 1)(x + 5) = 0$. Cada factor igual a cero da $x = \\dfrac{1}{3}$ y $x = -5$."},{"type":"input","kind":"set","q":"Resuelve la ecuación:\n$$2x^2 - 5x + 3 = 0$$\n\nEscribe todas las soluciones.","answer":"1; 3/2","why":"Factorizamos: $(2x - 3)(x - 1) = 0$. Cada factor igual a cero da $x = \\dfrac{3}{2}$ y $x = 1$."},{"q":"Resuelve la ecuación:\n$$3x^2 - 8x + 4 = 0$$","options":["$x=-\\dfrac{2}{3}$ y $x=2$","$x=\\dfrac{2}{3}$ y $x=2$","$x=-2$ y $x=-\\dfrac{2}{3}$","$x=-2$ y $x=\\dfrac{2}{3}$"],"correct":1,"why":"Factorizamos: $(3x - 2)(x - 2) = 0$. Cada factor igual a cero da $x = \\dfrac{2}{3}$ y $x = 2$."},{"type":"input","kind":"set","q":"Resuelve la ecuación:\n$$(x + 8)(x + 18) = 0$$\n\nEscribe todas las soluciones.","answer":"-18; -8","why":"Un producto es cero si algún factor es cero: $x + 8 = 0$ o $x + 18 = 0$."},{"q":"Resuelve la ecuación:\n$$(x + 2)(x + 15) = 0$$","options":["$x=-2$ y $x=15$","$x=-15$ y $x=-2$","$x=2$ y $x=15$","$x=-15$ y $x=2$"],"correct":1,"why":"Un producto es cero si algún factor es cero: $x + 2 = 0$ o $x + 15 = 0$."},{"q":"Resuelve la ecuación:\n$$(x + 5)(x + 18) = 0$$","options":["$x=5$ y $x=18$","$x=-18$ y $x=5$","$x=-18$ y $x=-5$","$x=-5$ y $x=18$"],"correct":2,"why":"Un producto es cero si algún factor es cero: $x + 5 = 0$ o $x + 18 = 0$."},{"q":"¿Cuál es la factorización de $x^2 + 9x + 20$?","options":["$(x + 4)(x - 5)$","$(x + 4)(x + 5)$","$(x - 4)(x - 5)$","$(x - 4)(x + 5)$"],"correct":1,"why":"Buscamos dos números que sumen 9 y multipliquen 20: son 4 y 5."},{"q":"¿Cuál es la factorización de $x^2 - 11x + 30$?","options":["$(x + 5)(x - 6)$","$(x + 5)(x + 6)$","$(x - 5)(x + 6)$","$(x - 5)(x - 6)$"],"correct":3,"why":"Buscamos dos números que sumen -11 y multipliquen 30: son -5 y -6."},{"q":"¿Cuál es la factorización de $x^2 - 1x - 30$?","options":["$(x - 6)(x - 5)$","$(x - 6)(x + 5)$","$(x + 6)(x + 5)$","$(x + 6)(x - 5)$"],"correct":1,"why":"Buscamos dos números que sumen -1 y multipliquen -30: son -6 y 5."}],"check":{"type":"input","kind":"number","q":"Un terreno rectangular para un experimento mide $x + 2$ metros de largo y $x$ metros de ancho, y su área es $15\\,\\mathrm{m}^2$, es decir, $x(x + 2) = 15$. ¿Cuánto mide el ancho del terreno? Escribe solo el número, en $\\mathrm{m}$.","answer":"3","why":"Llevamos la ecuación a la forma general y factorizamos: $x^2 + 2x - 15 = 0$, luego $(x + 5)(x - 3) = 0$. Solo $x = 3$ es válido como longitud."},"draw":5,"checks":[{"q":"Una parcela rectangular tiene un largo que mide $4\\,\\mathrm{m}$ más que su ancho $x$ y un área de $45\\,\\mathrm{m^2}$. ¿Cuánto mide el ancho?","options":["$5\\,\\mathrm{m}$","$9\\,\\mathrm{m}$","$\\dfrac{45}{2}\\,\\mathrm{m}$","$4\\,\\mathrm{m}$"],"correct":0,"why":"$x(x+4) = 45$ da $x^2 + 4x - 45 = 0$, que factoriza como $(x + 9)(x - 5) = 0$. Sirve $x = 5$."},{"type":"input","kind":"number","q":"Un invernadero rectangular tiene un largo $8\\,\\mathrm{m}$ mayor que su ancho $x$ y una superficie de $209\\,\\mathrm{m^2}$. ¿Cuál es su ancho? Escribe solo el número, en $\\mathrm{m}$.","answer":"11","why":"$x(x+8) = 209$ da $x^2 + 8x - 209 = 0$, que factoriza como $(x + 19)(x - 11) = 0$. Sirve $x = 11$."},{"q":"Una lámina rectangular de vidrio tiene un largo $8\\,\\mathrm{cm}$ mayor que su ancho $x$ y un área de $308\\,\\mathrm{cm^2}$. ¿Cuánto mide el ancho en cm?","options":["$13\\,\\mathrm{m}$","$22\\,\\mathrm{m}$","$14\\,\\mathrm{m}$","$154\\,\\mathrm{m}$"],"correct":2,"why":"$x(x+8) = 308$ da $x^2 + 8x - 308 = 0$, que factoriza como $(x + 22)(x - 14) = 0$. Sirve $x = 14$."},{"type":"input","kind":"number","q":"Una pelota se lanza desde un balcón y su altura es $h = -5t^2 + 10t + 40$ (en metros). ¿Después de cuántos segundos llega al suelo ($h = 0$)? Escribe solo el número, en $\\mathrm{s}$.","answer":"4","why":"Dividimos por $-5$: $t^2 - 2t - 8 = 0$. Factorizamos: $(t - 4)(t + 2) = 0$. Solo sirve $t = 4$."},{"q":"Un dron suelta una carga cuya altura es $h = -5t^2 + 25t + 70$ (en metros). ¿En cuántos segundos llega al suelo?","options":["$2\\,\\mathrm{s}$","$7\\,\\mathrm{s}$","$-2\\,\\mathrm{s}$","$9\\,\\mathrm{s}$"],"correct":1,"why":"Dividimos por $-5$: $t^2 - 5t - 14 = 0$. Factorizamos: $(t - 7)(t + 2) = 0$. Solo sirve $t = 7$."},{"type":"input","kind":"number","q":"Un cohete de agua sigue la trayectoria $h = -5t^2 + 20t + 25$. ¿En qué instante $t > 0$ toca el suelo? Escribe solo el número, en $\\mathrm{s}$.","answer":"5","why":"Dividimos por $-5$: $t^2 - 4t - 5 = 0$. Factorizamos: $(t - 5)(t + 1) = 0$. Solo sirve $t = 5$."},{"q":"Dos masas positivas (en gramos) suman $9$ y su producto es $14$. ¿Cuál es la mayor?","options":["$7$","$2$","$8$"],"correct":0,"why":"Con uno de ellos $x$: $x(9 - x) = 14$, o $x^2 - 9x + 14 = 0$, que factoriza como $(x - 2)(x - 7) = 0$. El mayor es 7."},{"type":"input","kind":"number","q":"Dos concentraciones positivas suman $18$ y su producto es $80$. ¿Cuál es la mayor?","answer":"10","why":"Con uno de ellos $x$: $x(18 - x) = 80$, o $x^2 - 18x + 80 = 0$, que factoriza como $(x - 8)(x - 10) = 0$. El mayor es 10."},{"q":"En un equilibrio químico se cumple $x(x + 3) = 54$, donde $x$ es una concentración positiva. ¿Cuánto vale $x$?","options":["$27$","$9$","$6$","$-9$"],"correct":2,"why":"$x(x+3) = 54$ da $x^2 + 3x - 54 = 0$, es decir $(x + 9)(x - 6) = 0$. Como $x>0$, $x = 6$."},{"type":"input","kind":"number","q":"En un modelo de reacción, el producto de una concentración $x$ por otra $(x + 5)$ vale $104$. Si $x>0$, ¿cuánto vale $x$?","answer":"8","why":"$x(x+5) = 104$ da $x^2 + 5x - 104 = 0$, es decir $(x + 13)(x - 8) = 0$. Como $x>0$, $x = 8$."},{"q":"Dos reactivos tienen concentraciones $x$ y $x + 5$ y su producto es $36$. ¿Cuánto vale $x$, si es positiva?","options":["$9$","$18$","$4$","$-9$"],"correct":2,"why":"$x(x+5) = 36$ da $x^2 + 5x - 36 = 0$, es decir $(x + 9)(x - 4) = 0$. Como $x>0$, $x = 4$."},{"type":"input","kind":"number","q":"Un rectángulo de $x$ por $x$ se amplía agregando $3\\,\\mathrm{m}$ a un lado y $5\\,\\mathrm{m}$ al otro, quedando con un área de $63\\,\\mathrm{m^2}$, es decir $(x + 3)(x + 5) = 63$. ¿Cuánto medía $x$? Escribe solo el número, en $\\mathrm{m}$.","answer":"4","why":"$(x + 3)(x + 5) = 63$ da $x^2 + 8x + 15 = 63$. Reduciendo, $(x - 4)(x + 12) = 0$, y $x = 4$."},{"q":"Un cultivo de $x$ por $x$ metros se amplía en $1\\,\\mathrm{m}$ y $6\\,\\mathrm{m}$ en sus lados, y el área final es $50\\,\\mathrm{m^2}$: $(x + 1)(x + 6) = 50$. ¿Cuánto medía $x$?","options":["$3\\,\\mathrm{m}$","$10\\,\\mathrm{m}$","$5\\,\\mathrm{m}$","$4\\,\\mathrm{m}$"],"correct":3,"why":"$(x + 1)(x + 6) = 50$ da $x^2 + 7x + 6 = 50$. Reduciendo, $(x - 4)(x + 11) = 0$, y $x = 4$."},{"q":"Un modelo de crecimiento de una población se describe con $x^2 - 3x - 28 = 0$. ¿Cuál es la factorización del lado izquierdo?","options":["$(x - 7)(x - 4)$","$(x + 7)(x - 4)$","$(x - 7)(x + 4)$","$(x + 7)(x + 4)$"],"correct":2,"why":"Buscamos dos números que sumen -3 y multipliquen -28: son -7 y 4."},{"q":"Un modelo físico lleva a la expresión $x^2 + 8x + 15$. ¿Cuál es su factorización?","options":["$(x - 3)(x - 5)$","$(x + 3)(x + 5)$","$(x - 3)(x + 5)$","$(x + 3)(x - 5)$"],"correct":1,"why":"Buscamos dos números que sumen 8 y multipliquen 15: son 3 y 5."},{"q":"Un sistema físico tiene como soluciones $x = 8$ y $x = 3$. ¿Cuál de estas ecuaciones las tiene como soluciones?","options":["$x^2 + 11x - 24 = 0$","$x^2 - 11x + 24 = 0$","$x^2 - 11x - 24 = 0$","$x^2 + 11x + 24 = 0$"],"correct":1,"why":"Si las soluciones son 8 y 3, la ecuación es $(x - (8))(x - (3)) = 0$, es decir $x^2 - (11)x + 24 = 0$."},{"q":"Las posiciones (en metros) en que se activa un sensor son $x = -6$ y $x = -7$. ¿Cuál de estas ecuaciones las tiene como soluciones?","options":["$x^2 + 13x + 42 = 0$","$x^2 - 13x - 42 = 0$","$x^2 + 13x - 42 = 0$","$x^2 - 13x + 42 = 0$"],"correct":0,"why":"Si las soluciones son -6 y -7, la ecuación es $(x - (-6))(x - (-7)) = 0$, es decir $x^2 - (-13)x + 42 = 0$."},{"type":"input","kind":"number","q":"Un laboratorio rectangular tiene un largo que mide $2\\,\\mathrm{m}$ más que su ancho $x$ y un área de $255\\,\\mathrm{m^2}$. ¿Cuánto mide el ancho? Escribe solo el número, en $\\mathrm{m}$.","answer":"15","why":"$x(x+2) = 255$ da $x^2 + 2x - 255 = 0$, que factoriza como $(x + 17)(x - 15) = 0$. Sirve $x = 15$."},{"q":"Un proyectil se dispara desde un risco y su altura es $h = -5t^2 + 5t + 30$ (en metros). ¿Después de cuántos segundos llega al suelo ($h = 0$)?","options":["$3\\,\\mathrm{s}$","$-2\\,\\mathrm{s}$","$2\\,\\mathrm{s}$","$5\\,\\mathrm{s}$"],"correct":0,"why":"Dividimos por $-5$: $t^2 - 1t - 6 = 0$. Factorizamos: $(t - 3)(t + 2) = 0$. Solo sirve $t = 3$."}],"drawCheck":5,"unit":0},{"id":"u3-s009","title":"Fórmula general","subtitle":"Resolver con los coeficientes","group":2,"symbol":"✧","minutes":50,"concept":"No toda ecuación cuadrática se factoriza con facilidad. La fórmula general resuelve cualquier ecuación $ax^2 + bx + c = 0$ con $a \\neq 0$ usando solo sus coeficientes:\n$$x = \\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a}$$\nEl signo $\\pm$ indica que se calculan dos valores, uno con $+$ y otro con $-$. Antes de reemplazar, conviene identificar $a$, $b$ y $c$ con sus signos.","example":"Resolvemos $2x^2 + 3x - 2 = 0$, con $a = 2$, $b = 3$ y $c = -2$:\n$$x = \\frac{-3 \\pm \\sqrt{3^2 - 4\\cdot 2\\cdot(-2)}}{2\\cdot 2} = \\frac{-3 \\pm 5}{4}$$\nEntonces $x = \\frac{-3 + 5}{4} = \\frac{1}{2}$ o $x = \\frac{-3 - 5}{4} = -2$.","media":[],"practice":[{"q":"En la ecuación $2x^2 - 3x + 5 = 0$, ¿cuáles son los valores de $a$, $b$ y $c$ en la forma general?","options":["$a = 2,\\ b = 3,\\ c = 5$","$a = -3,\\ b = 2,\\ c = 5$","$a = 2,\\ b = -3,\\ c = 5$"],"correct":2,"why":"Se comparan los coeficientes con la forma general $ax^2 + bx + c = 0$, respetando los signos."},{"q":"Resuelve con la fórmula general:\n$$2x^2 + 3x - 2 = 0$$","options":["$x = 2$ y $x = -\\tfrac{1}{2}$","$x = \\tfrac{1}{2}$ y $x = -2$","$x = 1$ y $x = -2$"],"correct":1,"why":"Con $a = 2$, $b = 3$ y $c = -2$: $x = \\frac{-3 \\pm \\sqrt{9 + 16}}{4} = \\frac{-3 \\pm 5}{4}$, de donde $x = \\frac{1}{2}$ o $x = -2$."},{"q":"En la ecuación $5x^2 + 6x - 2 = 0$, ¿cuáles son los valores de $a$, $b$ y $c$ en la forma general $ax^2 + bx + c = 0$?","options":["$a = 5,\\ b = -2,\\ c = 6$","$a = 5,\\ b = 6,\\ c = -2$","$a = 5,\\ b = 6,\\ c = 2$","$a = 5,\\ b = -6,\\ c = 2$"],"correct":1,"why":"El coeficiente de $x^2$ es $a$, el de $x$ es $b$ y el término sin $x$ es $c$, con sus signos."},{"q":"En la ecuación $6x^2 - 6x - 9 = 0$, ¿cuáles son los valores de $a$, $b$ y $c$ en la forma general $ax^2 + bx + c = 0$?","options":["$a = 6,\\ b = 6,\\ c = 9$","$a = 6,\\ b = -6,\\ c = -9$","$a = 6,\\ b = -9,\\ c = -6$"],"correct":1,"why":"El coeficiente de $x^2$ es $a$, el de $x$ es $b$ y el término sin $x$ es $c$, con sus signos."},{"q":"En la ecuación $2x^2 + 3x - 4 = 0$, ¿cuáles son los valores de $a$, $b$ y $c$ en la forma general $ax^2 + bx + c = 0$?","options":["$a = 2,\\ b = 3,\\ c = -4$","$a = 2,\\ b = -3,\\ c = 4$","$a = 2,\\ b = 3,\\ c = 4$","$a = 2,\\ b = -4,\\ c = 3$"],"correct":0,"why":"El coeficiente de $x^2$ es $a$, el de $x$ es $b$ y el término sin $x$ es $c$, con sus signos."},{"q":"En la ecuación $2x^2 + 6x - 2 = 0$, ¿cuáles son los valores de $a$, $b$ y $c$ en la forma general $ax^2 + bx + c = 0$?","options":["$a = 2,\\ b = 6,\\ c = 2$","$a = 2,\\ b = 6,\\ c = -2$","$a = 2,\\ b = -6,\\ c = 2$","$a = 2,\\ b = -2,\\ c = 6$"],"correct":1,"why":"El coeficiente de $x^2$ es $a$, el de $x$ es $b$ y el término sin $x$ es $c$, con sus signos."},{"type":"input","kind":"set","q":"Resuelve con la fórmula general:\n$$2x^2 - 5x - 12 = 0$$\n\nEscribe todas las soluciones.","answer":"-3/2; 4","why":"Aquí $a=2$, $b=-5$, $c=-12$ y $b^2-4ac=121$. Entonces $x=\\frac{5\\pm 11}{4}$, que da $-\\dfrac{3}{2}$ y $4$."},{"type":"input","kind":"set","q":"Resuelve con la fórmula general:\n$$9x^2 + 9x + 2 = 0$$\n\nEscribe todas las soluciones.","answer":"-2/3; -1/3","why":"Aquí $a=9$, $b=9$, $c=2$ y $b^2-4ac=9$. Entonces $x=\\frac{-9\\pm 3}{18}$, que da $-\\dfrac{2}{3}$ y $-\\dfrac{1}{3}$."},{"type":"input","kind":"set","q":"Resuelve con la fórmula general:\n$$2x^2 + 3x - 9 = 0$$\n\nEscribe todas las soluciones.","answer":"-3; 3/2","why":"Aquí $a=2$, $b=3$, $c=-9$ y $b^2-4ac=81$. Entonces $x=\\frac{-3\\pm 9}{4}$, que da $-3$ y $\\dfrac{3}{2}$."},{"type":"input","kind":"set","q":"Resuelve con la fórmula general:\n$$9x^2 - 18x + 5 = 0$$\n\nEscribe todas las soluciones.","answer":"1/3; 5/3","why":"Aquí $a=9$, $b=-18$, $c=5$ y $b^2-4ac=144$. Entonces $x=\\frac{18\\pm 12}{18}$, que da $\\dfrac{1}{3}$ y $\\dfrac{5}{3}$."},{"type":"input","kind":"set","q":"Resuelve con la fórmula general:\n$$9x^2 + 6x - 8 = 0$$\n\nEscribe todas las soluciones.","answer":"-4/3; 2/3","why":"Aquí $a=9$, $b=6$, $c=-8$ y $b^2-4ac=324$. Entonces $x=\\frac{-6\\pm 18}{18}$, que da $-\\dfrac{4}{3}$ y $\\dfrac{2}{3}$."},{"type":"input","kind":"set","q":"Resuelve con la fórmula general:\n$$4x^2 - 8x - 5 = 0$$\n\nEscribe todas las soluciones.","answer":"-1/2; 5/2","why":"Aquí $a=4$, $b=-8$, $c=-5$ y $b^2-4ac=144$. Entonces $x=\\frac{8\\pm 12}{8}$, que da $-\\dfrac{1}{2}$ y $\\dfrac{5}{2}$."},{"type":"input","kind":"set","q":"Resuelve con la fórmula general:\n$$6x^2 - 13x - 5 = 0$$\n\nEscribe todas las soluciones.","answer":"-1/3; 5/2","why":"Aquí $a=6$, $b=-13$, $c=-5$ y $b^2-4ac=289$. Entonces $x=\\frac{13\\pm 17}{12}$, que da $-\\dfrac{1}{3}$ y $\\dfrac{5}{2}$."},{"type":"input","kind":"set","q":"Resuelve con la fórmula general:\n$$2x^2 - 3x - 5 = 0$$\n\nEscribe todas las soluciones.","answer":"-1; 5/2","why":"Aquí $a=2$, $b=-3$, $c=-5$ y $b^2-4ac=49$. Entonces $x=\\frac{3\\pm 7}{4}$, que da $-1$ y $\\dfrac{5}{2}$."},{"q":"Resuelve con la fórmula general:\n$$x^2 - 6x + 2 = 0$$","options":["$x = 3 \\pm \\sqrt{8}$","$x = 3 \\pm \\sqrt{28}$","$x = 3 \\pm \\sqrt{7}$","$x = -3 \\pm \\sqrt{7}$"],"correct":2,"why":"Aquí $\\Delta=b^2-4ac=28$ y $x=\\frac{6\\pm\\sqrt{28}}{2}=3\\pm\\sqrt{7}$ (pues $\\sqrt{28}=2\\sqrt{7}$)."},{"q":"Resuelve con la fórmula general:\n$$x^2 - 8x + 10 = 0$$","options":["$x = -4 \\pm \\sqrt{6}$","$x = 4 \\pm \\sqrt{7}$","$x = 4 \\pm \\sqrt{24}$","$x = 4 \\pm \\sqrt{6}$"],"correct":3,"why":"Aquí $\\Delta=b^2-4ac=24$ y $x=\\frac{8\\pm\\sqrt{24}}{2}=4\\pm\\sqrt{6}$ (pues $\\sqrt{24}=2\\sqrt{6}$)."},{"q":"Al aplicar la fórmula general a la ecuación $x^2 - 5x - 3 = 0$, ¿qué expresión se obtiene para $x$?","options":["$x = \\dfrac{5 \\pm \\sqrt{13}}{2}$","$x = \\dfrac{5 \\pm \\sqrt{37}}{1}$","$x = \\dfrac{5 \\pm \\sqrt{37}}{2}$","$x = \\dfrac{-5 \\pm \\sqrt{37}}{2}$"],"correct":2,"why":"Con $a=1$, $b=-5$ y $c=-3$: $x=\\frac{-b\\pm\\sqrt{b^2-4ac}}{2a}=\\frac{5\\pm\\sqrt{37}}{2}$."},{"q":"Al aplicar la fórmula general a la ecuación $x^2 + 3x + 3 = 0$, ¿qué expresión se obtiene para $x$?","options":["$x = \\dfrac{3 \\pm \\sqrt{-3}}{2}$","$x = \\dfrac{-3 \\pm \\sqrt{21}}{2}$","$x = \\dfrac{-3 \\pm \\sqrt{-3}}{2}$","$x = \\dfrac{-3 \\pm \\sqrt{-3}}{1}$"],"correct":2,"why":"Con $a=1$, $b=3$ y $c=3$: $x=\\frac{-b\\pm\\sqrt{b^2-4ac}}{2a}=\\frac{-3\\pm\\sqrt{-3}}{2}$."},{"q":"Resuelve la ecuación aplicando la fórmula general (primero ordena la ecuación):\n$$3x^2 = -4x + 4$$","options":["$x=-\\dfrac{1}{2}$ y $x=\\dfrac{3}{2}$","$x=\\dfrac{2}{3}$","$x=-2$ y $x=\\dfrac{2}{3}$","$x=-\\dfrac{2}{3}$ y $x=2$"],"correct":2,"why":"Pasamos todo a la izquierda: $3x^2 + 4x - 4 = 0$. Con $a=3$, $b=4$, $c=-4$ se obtiene $x=-2$ y $x=\\dfrac{2}{3}$."},{"q":"Resuelve la ecuación aplicando la fórmula general (primero ordena la ecuación):\n$$3x^2 = 7x + 6$$","options":["$x=-\\dfrac{2}{3}$","$x=-3$ y $x=\\dfrac{2}{3}$","$x=-\\dfrac{3}{2}$ y $x=\\dfrac{1}{3}$","$x=-\\dfrac{2}{3}$ y $x=3$"],"correct":3,"why":"Pasamos todo a la izquierda: $3x^2 - 7x - 6 = 0$. Con $a=3$, $b=-7$, $c=-6$ se obtiene $x=-\\dfrac{2}{3}$ y $x=3$."}],"check":{"q":"Un objeto se lanza hacia arriba desde una plataforma a 15 m de altura. Su altura $h$ (en metros) después de $t$ segundos es $h(t) = -5t^2 + 10t + 15$. ¿En qué instante llega al suelo ($h = 0$)?","options":["$t = 3\\,\\mathrm{s}$","$t = 1\\,\\mathrm{s}$","$t = 5\\,\\mathrm{s}$"],"correct":0,"why":"Planteamos $h(t) = 0$ y dividimos por $-5$: $t^2 - 2t - 3 = 0$. Con la fórmula general, $t = \\frac{2 \\pm \\sqrt{16}}{2}$, es decir, $t = 3$ o $t = -1$. Se descarta la solución negativa porque el tiempo no puede ser negativo."},"draw":5,"checks":[{"type":"input","kind":"number","q":"Un objeto lanzado desde una altura sigue $h = -5t^2 - 15t + 50$ (en metros). Usa la fórmula general para hallar en qué instante $t>0$ toca el suelo ($h = 0$). Escribe solo el número, en $\\mathrm{s}$.","answer":"2","why":"$a=-5$, $b=-15$, $c=50$. La fórmula da $t = 2$ o $t = -5$; el tiempo es positivo, así que $t = 2$."},{"q":"La altura de una pelota es $h = -5t^2 - 5t + 60$. Aplica la fórmula general y halla cuándo $h = 0$ con $t>0$.","options":["$3\\,\\mathrm{s}$","$4\\,\\mathrm{s}$","$7\\,\\mathrm{s}$","$-4\\,\\mathrm{s}$"],"correct":0,"why":"$a=-5$, $b=-5$, $c=60$. La fórmula da $t = 3$ o $t = -4$; el tiempo es positivo, así que $t = 3$."},{"type":"input","kind":"number","q":"Un cohete de prueba tiene altura $h = -5t^2 + 25t + 70$. Usa la fórmula general para hallar cuándo llega al suelo ($t>0$). Escribe solo el número, en $\\mathrm{s}$.","answer":"7","why":"$a=-5$, $b=25$, $c=70$. La fórmula da $t = 7$ o $t = -2$; el tiempo es positivo, así que $t = 7$."},{"q":"Un proyectil sigue $h = -5t^2 + 15t + 50$ (en metros). ¿En qué instante $t>0$ llega al suelo?","options":["$2\\,\\mathrm{s}$","$5\\,\\mathrm{s}$","$-2\\,\\mathrm{s}$","$7\\,\\mathrm{s}$"],"correct":1,"why":"$a=-5$, $b=15$, $c=50$. La fórmula da $t = 5$ o $t = -2$; el tiempo es positivo, así que $t = 5$."},{"type":"input","kind":"number","q":"Una partícula cumple $5t^2 - 7t - 3 = 0$, con $t$ en segundos. Usa la fórmula general y entrega la solución positiva aproximada a un decimal. Escribe solo el número, en $\\mathrm{s}$.","answer":"1,7","why":"Con $a=5$, $b=-7$, $c=-3$: $\\Delta=109$ y $t=\\frac{7+\\sqrt{109}}{10}\\approx 1{,}7$ (la otra solución es negativa)."},{"q":"En un modelo de caída, $5t^2 - 3t - 6 = 0$ ($t$ en s). Calcula con la fórmula general el valor positivo de $t$, con un decimal.","options":["$0{,}8\\,\\mathrm{s}$","$2{,}9\\,\\mathrm{s}$","$-0{,}8\\,\\mathrm{s}$","$1{,}4\\,\\mathrm{s}$"],"correct":3,"why":"Con $a=5$, $b=-3$, $c=-6$: $\\Delta=129$ y $t=\\frac{3+\\sqrt{129}}{10}\\approx 1{,}4$ (la otra solución es negativa)."},{"type":"input","kind":"number","q":"Una reacción sigue $5t^2 - 7t - 1 = 0$ ($t$ en horas). Con la fórmula general, ¿cuál es la solución positiva aproximada a un decimal? Escribe solo el número, en $\\mathrm{h}$.","answer":"1,5","why":"Con $a=5$, $b=-7$, $c=-1$: $\\Delta=69$ y $t=\\frac{7+\\sqrt{69}}{10}\\approx 1{,}5$ (la otra solución es negativa)."},{"q":"La profundidad de un sensor cumple $5t^2 - 2t - 8 = 0$ ($t$ en minutos). Halla con la fórmula general la solución positiva, con un decimal.","options":["$1{,}5\\,\\mathrm{min}$","$-1{,}1\\,\\mathrm{min}$","$3{,}0\\,\\mathrm{min}$","$1{,}1\\,\\mathrm{min}$"],"correct":0,"why":"Con $a=5$, $b=-2$, $c=-8$: $\\Delta=164$ y $t=\\frac{2+\\sqrt{164}}{10}\\approx 1{,}5$ (la otra solución es negativa)."},{"type":"input","kind":"number","q":"Un panel solar rectangular tiene un ancho $x$ y un largo $(2x + 1)$ metros. Si su área es $105\\,\\mathrm{m^2}$, ¿cuánto mide el ancho? Escribe solo el número, en $\\mathrm{m}$.","answer":"7","why":"$x(2x+1) = 105$ da $2x^2 + x - 105 = 0$. La fórmula general entrega $x = 7$ (la otra solución es negativa)."},{"q":"Una parcela rectangular tiene un ancho $x$ y un largo $(2x + 1)$ metros, con un área de $21\\,\\mathrm{m^2}$. ¿Cuánto mide el ancho?","options":["$3\\,\\mathrm{m}$","$7\\,\\mathrm{m}$","$2\\,\\mathrm{m}$","$4\\,\\mathrm{m}$"],"correct":0,"why":"$x(2x+1) = 21$ da $2x^2 + x - 21 = 0$. La fórmula general entrega $x = 3$ (la otra solución es negativa)."},{"type":"input","kind":"number","q":"Una placa de cultivo rectangular mide $x$ de ancho y $(2x + 1)$ cm de largo, con un área de $55\\,\\mathrm{cm^2}$. ¿Cuánto mide el ancho en cm? Escribe solo el número, en $\\mathrm{m}$.","answer":"5","why":"$x(2x+1) = 55$ da $2x^2 + x - 55 = 0$. La fórmula general entrega $x = 5$ (la otra solución es negativa)."},{"q":"El número de bacterias (en miles) sigue $P(t) = -t^2 + 2t + 3$, con $t$ en horas. ¿En qué instante $t>0$ se extingue la población ($P = 0$)?","options":["$-1$","$4$","$3$","$2$"],"correct":2,"why":"$a=-1$, $b=2$, $c=3$. La fórmula da $t = 3$ o $t = -1$; solo sirve $t = 3$."},{"type":"input","kind":"number","q":"La población (en miles) de una colonia es $P(t) = -t^2 + 9t + 10$ ($t$ en días). Con la fórmula general, ¿cuándo $P = 0$ con $t>0$?","answer":"10","why":"$a=-1$, $b=9$, $c=10$. La fórmula da $t = 10$ o $t = -1$; solo sirve $t = 10$."},{"q":"Un cultivo de algas (en miles) cumple $P(t) = -t^2 + 4t + 5$, con $t$ en semanas. ¿En qué instante $t>0$ llega a cero?","options":["$6$","$5$","$-1$","$4$"],"correct":1,"why":"$a=-1$, $b=4$, $c=5$. La fórmula da $t = 5$ o $t = -1$; solo sirve $t = 5$."},{"type":"input","kind":"number","q":"En un equilibrio químico, la concentración $x$ cumple $2x^2 - 5x - 12 = 0$. Hay una única solución positiva. ¿Cuánto vale?","answer":"4","why":"Con $a=2$, $b=-5$, $c=-12$ la fórmula da $x = -\\dfrac{3}{2}$ o $x = 4$; la concentración positiva es $4$."},{"q":"El movimiento de un objeto se describe con $4t^2 + 1t - 3 = 0$. Para usar la fórmula general, ¿cuáles son $a$, $b$ y $c$?","options":["$a = 4,\\ b = -3,\\ c = 1$","$a = 4,\\ b = 1,\\ c = -3$","$a = 4,\\ b = -1,\\ c = 3$","$a = 4,\\ b = 1,\\ c = 3$"],"correct":1,"why":"El coeficiente de $t^2$ es $a$, el de $t$ es $b$ y el término sin $t$ es $c$, con sus signos."},{"q":"Un modelo de reacción se expresa como $4t^2 + 5t + 7 = 0$. ¿Cuáles son los valores de $a$, $b$ y $c$ en la forma general?","options":["$a = 4,\\ b = 7,\\ c = 5$","$a = 4,\\ b = -5,\\ c = -7$","$a = 4,\\ b = 5,\\ c = 7$"],"correct":2,"why":"El coeficiente de $t^2$ es $a$, el de $t$ es $b$ y el término sin $t$ es $c$, con sus signos."},{"q":"Una piedra lanzada desde un puente sigue $h = -5t^2 - 5t + 150$ (en metros). Con la fórmula general, ¿en qué instante $t>0$ toca el agua?","options":["$-6\\,\\mathrm{s}$","$11\\,\\mathrm{s}$","$5\\,\\mathrm{s}$","$6\\,\\mathrm{s}$"],"correct":2,"why":"$a=-5$, $b=-5$, $c=150$. La fórmula da $t = 5$ o $t = -6$; el tiempo es positivo, así que $t = 5$."},{"q":"El nivel de una sustancia cumple $5t^2 - 2t - 9 = 0$ ($t$ en minutos). Usa la fórmula general y da la solución positiva con un decimal.","options":["$3{,}1\\,\\mathrm{min}$","$1{,}2\\,\\mathrm{min}$","$1{,}6\\,\\mathrm{min}$","$-1{,}2\\,\\mathrm{min}$"],"correct":2,"why":"Con $a=5$, $b=-2$, $c=-9$: $\\Delta=184$ y $t=\\frac{2+\\sqrt{184}}{10}\\approx 1{,}6$ (la otra solución es negativa)."}],"drawCheck":5,"unit":0},{"id":"u3-s010","title":"Discriminante","subtitle":"Cuántas soluciones reales hay","group":2,"symbol":"✧","minutes":40,"concept":"La expresión bajo la raíz en la fórmula general se llama discriminante: $\\Delta = b^2 - 4ac$. Permite saber cuántas soluciones reales tiene la ecuación sin resolverla:\n• Si $\\Delta > 0$, hay dos soluciones reales distintas.\n• Si $\\Delta = 0$, hay una única solución real.\n• Si $\\Delta < 0$, no hay soluciones reales, porque no existe la raíz cuadrada de un número negativo en los números reales.","example":"Analizamos $x^2 + 2x + 5 = 0$, con $a = 1$, $b = 2$ y $c = 5$:\n$$\\Delta = 2^2 - 4\\cdot 1\\cdot 5 = 4 - 20 = -16 < 0$$\nComo el discriminante es negativo, la ecuación no tiene soluciones reales.","media":[],"practice":[{"type":"input","kind":"number","q":"Calcula el discriminante de la ecuación:\n$$x^2 - 6x + 9 = 0$$\n\nEscribe el valor de $\\Delta$.","answer":"0","why":"Con $a = 1$, $b = -6$ y $c = 9$: $\\Delta = (-6)^2 - 4\\cdot 1\\cdot 9 = 36 - 36 = 0$."},{"q":"¿Cuántas soluciones reales tiene la ecuación?\n$$x^2 + 2x + 5 = 0$$","options":["Ninguna","Una","Dos"],"correct":0,"why":"El discriminante es negativo, por lo que no hay soluciones reales: $\\Delta = 2^2 - 4\\cdot 1\\cdot 5 = -16 < 0$."},{"type":"input","kind":"number","q":"Calcula el discriminante $\\Delta = b^2 - 4ac$ de la ecuación:\n$$2x^2 - 8x + 1 = 0$$\n\nEscribe el valor de $\\Delta$.","answer":"56","why":"Con $a=2$, $b=-8$, $c=1$: $\\Delta=(-8)^2-4\\cdot 2\\cdot(1)=56$."},{"type":"input","kind":"number","q":"Calcula el discriminante $\\Delta = b^2 - 4ac$ de la ecuación:\n$$2x^2 + 8x + 6 = 0$$\n\nEscribe el valor de $\\Delta$.","answer":"16","why":"Con $a=2$, $b=8$, $c=6$: $\\Delta=(8)^2-4\\cdot 2\\cdot(6)=16$."},{"type":"input","kind":"number","q":"Calcula el discriminante $\\Delta = b^2 - 4ac$ de la ecuación:\n$$x^2 - 7x - 3 = 0$$\n\nEscribe el valor de $\\Delta$.","answer":"61","why":"Con $a=1$, $b=-7$, $c=-3$: $\\Delta=(-7)^2-4\\cdot 1\\cdot(-3)=61$."},{"type":"input","kind":"number","q":"Calcula el discriminante $\\Delta = b^2 - 4ac$ de la ecuación:\n$$4x^2 - 3x + 2 = 0$$\n\nEscribe el valor de $\\Delta$.","answer":"-23","why":"Con $a=4$, $b=-3$, $c=2$: $\\Delta=(-3)^2-4\\cdot 4\\cdot(2)=-23$."},{"type":"input","kind":"number","q":"Calcula el discriminante $\\Delta = b^2 - 4ac$ de la ecuación:\n$$4x^2 - 8x + 2 = 0$$\n\nEscribe el valor de $\\Delta$.","answer":"32","why":"Con $a=4$, $b=-8$, $c=2$: $\\Delta=(-8)^2-4\\cdot 4\\cdot(2)=32$."},{"type":"input","kind":"number","q":"Calcula el discriminante $\\Delta = b^2 - 4ac$ de la ecuación:\n$$2x^2 - 4x + 5 = 0$$\n\nEscribe el valor de $\\Delta$.","answer":"-24","why":"Con $a=2$, $b=-4$, $c=5$: $\\Delta=(-4)^2-4\\cdot 2\\cdot(5)=-24$."},{"q":"¿Cuántas soluciones reales tiene la ecuación?\n$$x^2 - 3x + 1 = 0$$","options":["Una solución real (doble)","Infinitas soluciones","Ninguna solución real","Dos soluciones reales distintas"],"correct":3,"why":"$\\Delta = (-3)^2 - 4\\cdot 1\\cdot(1) = 5$, que es positivo."},{"q":"¿Cuántas soluciones reales tiene la ecuación?\n$$3x^2 + 2x + 5 = 0$$","options":["Una solución real (doble)","Dos soluciones reales distintas","Ninguna solución real","Infinitas soluciones"],"correct":2,"why":"$\\Delta = (2)^2 - 4\\cdot 3\\cdot(5) = -56$, que es negativo."},{"q":"¿Cuántas soluciones reales tiene la ecuación?\n$$2x^2 + 8x + 8 = 0$$","options":["Infinitas soluciones","Ninguna solución real","Dos soluciones reales distintas","Una solución real (doble)"],"correct":3,"why":"$\\Delta = (8)^2 - 4\\cdot 2\\cdot(8) = 0$, que es cero."},{"q":"¿Cuántas soluciones reales tiene la ecuación?\n$$3x^2 + 2x - 6 = 0$$","options":["Una solución real (doble)","Infinitas soluciones","Ninguna solución real","Dos soluciones reales distintas"],"correct":3,"why":"$\\Delta = (2)^2 - 4\\cdot 3\\cdot(-6) = 76$, que es positivo."},{"q":"¿Cuántas soluciones reales tiene la ecuación?\n$$2x^2 + 3x + 5 = 0$$","options":["Infinitas soluciones","Dos soluciones reales distintas","Una solución real (doble)","Ninguna solución real"],"correct":3,"why":"$\\Delta = (3)^2 - 4\\cdot 2\\cdot(5) = -31$, que es negativo."},{"q":"¿Cuántas soluciones reales tiene la ecuación?\n$$3x^2 - 6x + 3 = 0$$","options":["Infinitas soluciones","Una solución real (doble)","Ninguna solución real","Dos soluciones reales distintas"],"correct":1,"why":"$\\Delta = (-6)^2 - 4\\cdot 3\\cdot(3) = 0$, que es cero."},{"q":"¿Para qué valores de $k$ la ecuación $x^2 + kx + 4 = 0$ tiene exactamente una solución real?","options":["$k = 2$ o $k = -2$","Solo $k = 4$","$k = 4$ o $k = -4$"],"correct":2,"why":"Se necesita $\\Delta = k^2 - 4\\cdot 4 = 0$, luego $k^2 = 16$ y $k = \\pm 4$."},{"q":"¿Para qué valores de $k$ la ecuación $x^2 + kx + 25 = 0$ tiene exactamente una solución real?","options":["$k = 10$ o $k = -10$","Solo $k = 10$","$k = 25$ o $k = -25$","$k = 5$ o $k = -5$"],"correct":0,"why":"Se necesita $\\Delta = k^2 - 4\\cdot 25 = 0$, luego $k^2 = 100$ y $k = \\pm 10$."},{"q":"¿Para qué valores de $k$ la ecuación $x^2 + kx + 9 = 0$ tiene exactamente una solución real?","options":["$k = 6$ o $k = -6$","Solo $k = 6$","$k = 3$ o $k = -3$","$k = 9$ o $k = -9$"],"correct":0,"why":"Se necesita $\\Delta = k^2 - 4\\cdot 9 = 0$, luego $k^2 = 36$ y $k = \\pm 6$."},{"q":"Si el discriminante de una ecuación cuadrática es $\\Delta = -11$, ¿qué se puede afirmar?","options":["Tiene dos soluciones reales distintas","No tiene soluciones reales","Tiene exactamente una solución real","Tiene soluciones reales, pero son negativas"],"correct":1,"why":"Si $\\Delta < 0$, la raíz de $\\Delta$ no es un número real."},{"q":"Si el discriminante de una ecuación cuadrática es $\\Delta = 81$, ¿qué se puede afirmar?","options":["No tiene soluciones reales","Tiene infinitas soluciones","Tiene exactamente una solución real","Tiene dos soluciones reales distintas"],"correct":3,"why":"Si $\\Delta > 0$ hay dos soluciones reales distintas."},{"q":"Si $\\Delta = 0$ en una ecuación cuadrática, la fórmula general $x = \\dfrac{-b \\pm \\sqrt{\\Delta}}{2a}$ entrega:","options":["Siempre $x = 0$","Un único valor: $x = \\dfrac{-b}{2a}$","Dos valores distintos","Ningún valor real"],"correct":1,"why":"Con $\\Delta=0$ la raíz es 0, y el $\\pm$ no cambia el resultado."}],"check":{"q":"La altura (en metros) de un proyectil en el instante $t$ (en segundos) es $h(t) = -t^2 + 4t$. Para que el proyectil alcance una altura $k$ en un único instante, la ecuación $-t^2 + 4t = k$ debe tener una sola solución real. ¿Cuánto vale $k$?","options":["$k = 2$","$k = 4$","$k = 16$"],"correct":1,"why":"Escribimos la ecuación en forma general, $-t^2 + 4t - k = 0$, e igualamos el discriminante a cero: $\\Delta = 4^2 - 4(-1)(-k) = 16 - 4k = 0$, de donde $k = 4$."},"draw":5,"checks":[{"q":"La altura de una pelota lanzada hacia arriba es $h = -5t^2 + 21t$ (en metros). ¿Alcanza la pelota una altura de $12\\,\\mathrm{m}$?","options":["Sí, pero solo la toca una vez (en su punto más alto)","Sí, y la pasa dos veces","No se puede saber","No, nunca la alcanza"],"correct":1,"why":"Igualamos $-5t^2 + 21t = 12$, o $5t^2 - 21t + 12 = 0$. Su discriminante es $\\Delta = (21)^2 - 4\\cdot5\\cdot12 = 201$, que es positivo."},{"q":"La altura de una pelota lanzada hacia arriba es $h = -5t^2 + 10t$ (en metros). ¿Alcanza la pelota una altura de $5\\,\\mathrm{m}$?","options":["Sí, pero solo la toca una vez (en su punto más alto)","No se puede saber","Sí, y la pasa dos veces","No, nunca la alcanza"],"correct":0,"why":"Igualamos $-5t^2 + 10t = 5$, o $5t^2 - 10t + 5 = 0$. Su discriminante es $\\Delta = (10)^2 - 4\\cdot5\\cdot5 = 0$, que es cero."},{"q":"La altura de una pelota lanzada hacia arriba es $h = -5t^2 + 4t$ (en metros). ¿Alcanza la pelota una altura de $23\\,\\mathrm{m}$?","options":["No, nunca la alcanza","No se puede saber","Sí, y la pasa dos veces","Sí, pero solo la toca una vez (en su punto más alto)"],"correct":0,"why":"Igualamos $-5t^2 + 4t = 23$, o $5t^2 - 4t + 23 = 0$. Su discriminante es $\\Delta = (4)^2 - 4\\cdot5\\cdot23 = -444$, que es negativo."},{"q":"La altura de una pelota lanzada hacia arriba es $h = -5t^2 + 24t$ (en metros). ¿Alcanza la pelota una altura de $25\\,\\mathrm{m}$?","options":["No se puede saber","Sí, y la pasa dos veces","Sí, pero solo la toca una vez (en su punto más alto)","No, nunca la alcanza"],"correct":1,"why":"Igualamos $-5t^2 + 24t = 25$, o $5t^2 - 24t + 25 = 0$. Su discriminante es $\\Delta = (24)^2 - 4\\cdot5\\cdot25 = 76$, que es positivo."},{"q":"La altura de una pelota lanzada hacia arriba es $h = -5t^2 + 17t$ (en metros). ¿Alcanza la pelota una altura de $23\\,\\mathrm{m}$?","options":["No, nunca la alcanza","Sí, pero solo la toca una vez (en su punto más alto)","Sí, y la pasa dos veces","No se puede saber"],"correct":0,"why":"Igualamos $-5t^2 + 17t = 23$, o $5t^2 - 17t + 23 = 0$. Su discriminante es $\\Delta = (17)^2 - 4\\cdot5\\cdot23 = -171$, que es negativo."},{"q":"Un dron sigue la altura $h = -5t^2 + 12t$ (en metros). ¿Cuántas veces pasa por los $2\\,\\mathrm{m}$ de altura?","options":["Ninguna vez","Una vez","Infinitas veces","Dos veces"],"correct":3,"why":"$\\Delta = (12)^2 - 4\\cdot5\\cdot2 = 104$, que es positivo: dos soluciones reales."},{"q":"Un dron sigue la altura $h = -5t^2 + 11t$ (en metros). ¿Cuántas veces pasa por los $23\\,\\mathrm{m}$ de altura?","options":["Dos veces","Una vez","Ninguna vez","Infinitas veces"],"correct":2,"why":"$\\Delta = (11)^2 - 4\\cdot5\\cdot23 = -339$, que es negativo: ninguna solución real."},{"q":"Un dron sigue la altura $h = -5t^2 + 10t$ (en metros). ¿Cuántas veces pasa por los $5\\,\\mathrm{m}$ de altura?","options":["Una vez","Infinitas veces","Ninguna vez","Dos veces"],"correct":0,"why":"$\\Delta = (10)^2 - 4\\cdot5\\cdot5 = 0$, que es cero: una solución real."},{"q":"Un dron sigue la altura $h = -5t^2 + 29t$ (en metros). ¿Cuántas veces pasa por los $11\\,\\mathrm{m}$ de altura?","options":["Una vez","Dos veces","Ninguna vez","Infinitas veces"],"correct":1,"why":"$\\Delta = (29)^2 - 4\\cdot5\\cdot11 = 621$, que es positivo: dos soluciones reales."},{"type":"input","kind":"number","q":"La trayectoria de un objeto se modela con $2t^2 - 3t - 1 = 0$. Calcula el discriminante $\\Delta = b^2 - 4ac$.\n\nEscribe el valor de $\\Delta$.","answer":"17","why":"Con $a=2$, $b=-3$, $c=-1$: $\\Delta=(-3)^2-4\\cdot2\\cdot(-1)=17$."},{"type":"input","kind":"number","q":"Un modelo de reacción lleva a $5t^2 - 3t + 5 = 0$. ¿Cuánto vale su discriminante?\n\nEscribe el valor de $\\Delta$.","answer":"-91","why":"Con $a=5$, $b=-3$, $c=5$: $\\Delta=(-3)^2-4\\cdot5\\cdot(5)=-91$."},{"type":"input","kind":"number","q":"El movimiento de una partícula cumple $4t^2 + 5t + 4 = 0$. Calcula $\\Delta = b^2 - 4ac$.\n\nEscribe el valor de $\\Delta$.","answer":"-39","why":"Con $a=4$, $b=5$, $c=4$: $\\Delta=(5)^2-4\\cdot4\\cdot(4)=-39$."},{"type":"input","kind":"number","q":"Una población sigue $2t^2 - 6t - 8 = 0$. ¿Cuánto vale el discriminante?\n\nEscribe el valor de $\\Delta$.","answer":"100","why":"Con $a=2$, $b=-6$, $c=-8$: $\\Delta=(-6)^2-4\\cdot2\\cdot(-8)=100$."},{"q":"Un modelo de trayectoria $x^2 + kx + 4 = 0$ debe tener exactamente una solución real. ¿Qué valores puede tomar $k$?","options":["Solo $k = 4$","$k = 2$ o $k = -2$","$k = 4$ o $k = -4$"],"correct":2,"why":"Se necesita $\\Delta = k^2 - 4\\cdot4 = 0$, luego $k^2 = 16$ y $k = \\pm 4$."},{"q":"Para que la ecuación $x^2 + kx + 4 = 0$ de un sistema químico tenga una única solución real, ¿cuánto debe valer $k$?","options":["$k = 2$ o $k = -2$","Solo $k = 4$","$k = 4$ o $k = -4$"],"correct":2,"why":"Se necesita $\\Delta = k^2 - 4\\cdot4 = 0$, luego $k^2 = 16$ y $k = \\pm 4$."},{"q":"Un sensor modela su error con $x^2 + kx + 25 = 0$. Si debe haber exactamente una solución real, ¿qué valores puede tener $k$?","options":["$k = 25$ o $k = -25$","$k = 5$ o $k = -5$","Solo $k = 10$","$k = 10$ o $k = -10$"],"correct":3,"why":"Se necesita $\\Delta = k^2 - 4\\cdot25 = 0$, luego $k^2 = 100$ y $k = \\pm 10$."},{"q":"Un modelo predice cuándo una pelota llega a cierta altura. Su ecuación tiene discriminante $\\Delta = -18$. ¿Qué se concluye?","options":["Ocurre infinitas veces","No tiene soluciones reales, es decir, el evento no ocurre","Ocurre dos veces","Ocurre exactamente una vez"],"correct":1,"why":"Si $\\Delta < 0$, no hay soluciones reales."},{"q":"Un modelo predice cuándo un sensor registra cierto valor. Su ecuación tiene discriminante $\\Delta = 0$. ¿Qué se concluye?","options":["No ocurre nunca","Ocurre dos veces","Ocurre exactamente una vez","Ocurre infinitas veces"],"correct":2,"why":"Si $\\Delta = 0$, hay una única solución real."},{"q":"Un modelo predice cuándo una población alcanza cierto tamaño. Su ecuación tiene discriminante $\\Delta = 4$. ¿Qué se concluye?","options":["Ocurre exactamente una vez","Ocurre dos veces","No ocurre nunca","Ocurre infinitas veces"],"correct":1,"why":"Si $\\Delta > 0$, hay dos soluciones reales distintas."}],"drawCheck":5,"unit":0},{"id":"u3-s011","title":"Problemas cuadráticos","subtitle":"Áreas, productos y movimiento","group":3,"symbol":"✧","minutes":50,"concept":"Los problemas de áreas, de productos de números y de movimiento vertical suelen llevar a ecuaciones cuadráticas. Se sigue el mismo método que en los problemas lineales: definir la incógnita, plantear la ecuación, llevarla a la forma $ax^2 + bx + c = 0$, resolverla (factorizando o con la fórmula general) y revisar cada solución en el contexto.\n\nCon frecuencia una de las dos soluciones no tiene sentido (por ejemplo, un tiempo o una longitud negativos) y se descarta.","example":"Un rectángulo tiene un área de $45\\,\\mathrm{cm}^2$ y su largo mide 4 cm más que su ancho. Si el ancho es $x$:\n$$x(x + 4) = 45 \\quad\\Rightarrow\\quad x^2 + 4x - 45 = 0 \\quad\\Rightarrow\\quad (x + 9)(x - 5) = 0$$\nLas soluciones son $x = -9$ y $x = 5$; se descarta $-9$ porque una longitud no puede ser negativa. El ancho mide 5 cm.","media":[],"practice":[{"type":"input","kind":"number","q":"El producto de dos números positivos consecutivos es 56. ¿Cuál es el menor de ellos?","answer":"7","why":"Si el menor es $x$, el siguiente es $x + 1$: $x(x + 1) = 56$, luego $x^2 + x - 56 = 0$ y $(x + 8)(x - 7) = 0$. Se descarta la solución negativa y queda $x = 7$."},{"q":"Un rectángulo tiene un área de $45\\,\\mathrm{cm}^2$ y su largo mide 4 cm más que su ancho. ¿Cuánto mide el ancho?","options":["$9\\,\\mathrm{cm}$","$45\\,\\mathrm{cm}$","$5\\,\\mathrm{cm}$"],"correct":2,"why":"Si el ancho es $x$, el largo es $x + 4$: $x(x + 4) = 45$, luego $x^2 + 4x - 45 = 0$ y $(x + 9)(x - 5) = 0$. La solución válida es $x = 5$."},{"type":"input","kind":"number","q":"El producto de dos números positivos consecutivos es 110. ¿Cuál es el mayor de ellos?","answer":"11","why":"Con $x$ el menor: $x(x+1)=110$, luego $x^2+x-110=0$ y $(x+11)(x-10)=0$. Como es positivo, $x=10$ y el mayor es 11."},{"q":"El producto de dos números positivos consecutivos es 272. ¿Cuál es el mayor de ellos?","options":["136","17","16","18"],"correct":1,"why":"Con $x$ el menor: $x(x+1)=272$, luego $x^2+x-272=0$ y $(x+17)(x-16)=0$. Como es positivo, $x=16$ y el mayor es 17."},{"type":"input","kind":"number","q":"El producto de dos números positivos consecutivos es 90. ¿Cuál es el mayor de ellos?","answer":"10","why":"Con $x$ el menor: $x(x+1)=90$, luego $x^2+x-90=0$ y $(x+10)(x-9)=0$. Como es positivo, $x=9$ y el mayor es 10."},{"q":"Un rectángulo tiene un área de $91\\,\\mathrm{cm}^2$ y su largo mide 6 cm más que su ancho. ¿Cuánto mide el ancho?","options":["$13\\,\\mathrm{cm}$","$6\\,\\mathrm{cm}$","$7\\,\\mathrm{cm}$","$8\\,\\mathrm{cm}$"],"correct":2,"why":"Con ancho $x$: $x(x+6)=91$; luego $x^2+6x-91=0$ y $x=7$."},{"type":"input","kind":"number","q":"Un rectángulo tiene un área de $240\\,\\mathrm{cm}^2$ y su largo mide 8 cm más que su ancho. ¿Cuánto mide el ancho? Escribe solo el número, en $\\mathrm{cm}$.","answer":"12","why":"Con ancho $x$: $x(x+8)=240$; luego $x^2+8x-240=0$ y $x=12$."},{"q":"Un rectángulo tiene un área de $27\\,\\mathrm{cm}^2$ y su largo mide 6 cm más que su ancho. ¿Cuánto mide el largo?","options":["$3\\,\\mathrm{cm}$","$15\\,\\mathrm{cm}$","$9\\,\\mathrm{cm}$"],"correct":2,"why":"El ancho es $x=3$ (de $x(x+6)=27$); el largo es $x+6=9$."},{"type":"input","kind":"number","q":"Un rectángulo tiene un área de $294\\,\\mathrm{cm}^2$ y su largo mide 7 cm más que su ancho. ¿Cuánto mide el largo? Escribe solo el número, en $\\mathrm{cm}$.","answer":"21","why":"El ancho es $x=14$ (de $x(x+7)=294$); el largo es $x+7=21$."},{"q":"Un cuadrado se amplía agregando 5 cm a cada lado y su área pasa a ser $81\\,\\mathrm{cm}^2$. ¿Cuánto medía el lado original?","options":["$20\\,\\mathrm{cm}$","$14\\,\\mathrm{cm}$","$4\\,\\mathrm{cm}$","$9\\,\\mathrm{cm}$"],"correct":2,"why":"$(x+5)^2=81$ da $x+5=9$, luego $x=4$ (se descarta el valor negativo)."},{"type":"input","kind":"number","q":"Un cuadrado se amplía agregando 1 cm a cada lado y su área pasa a ser $9\\,\\mathrm{cm}^2$. ¿Cuánto medía el lado original? Escribe solo el número, en $\\mathrm{cm}$.","answer":"2","why":"$(x+1)^2=9$ da $x+1=3$, luego $x=2$ (se descarta el valor negativo)."},{"q":"El cuadrado de un número positivo, más 1 veces ese número, es igual a 42. ¿Cuál es el número?","options":["-7","6","21","7"],"correct":1,"why":"$x^2+1x=42$ equivale a $x^2+1x-42=0$, cuyas soluciones son $x=6$ y $x=-7$. El número positivo es 6."},{"type":"input","kind":"number","q":"El cuadrado de un número positivo, más 3 veces ese número, es igual a 88. ¿Cuál es el número?","answer":"8","why":"$x^2+3x=88$ equivale a $x^2+3x-88=0$, cuyas soluciones son $x=8$ y $x=-11$. El número positivo es 8."},{"q":"La altura (en metros) de una pelota lanzada hacia arriba es $h(t) = -5t^2 + 15t$, con $t$ en segundos. ¿En qué instante vuelve al suelo ($h = 0$)?","options":["$t = 0\\ \\mathrm{s}$","$t = 15\\ \\mathrm{s}$","$t = 3\\ \\mathrm{s}$","$t = \\dfrac{3}{2}\\ \\mathrm{s}$"],"correct":2,"why":"Factorizamos $-5t^2+15t=-5t(t-3)=0$. Sirve $t=3$ s (el $t=0$ es el lanzamiento)."},{"q":"La altura (en metros) de una pelota lanzada hacia arriba es $h(t) = -5t^2 + 20t$, con $t$ en segundos. ¿En qué instante vuelve al suelo ($h = 0$)?","options":["$t = 4\\ \\mathrm{s}$","$t = 20\\ \\mathrm{s}$","$t = 2\\ \\mathrm{s}$","$t = 0\\ \\mathrm{s}$"],"correct":0,"why":"Factorizamos $-5t^2+20t=-5t(t-4)=0$. Sirve $t=4$ s (el $t=0$ es el lanzamiento)."},{"q":"La altura (en metros) de una pelota lanzada hacia arriba es $h(t) = -5t^2 + 25t$, con $t$ en segundos. ¿En qué instante vuelve al suelo ($h = 0$)?","options":["$t = \\dfrac{5}{2}\\ \\mathrm{s}$","$t = 25\\ \\mathrm{s}$","$t = 0\\ \\mathrm{s}$","$t = 5\\ \\mathrm{s}$"],"correct":3,"why":"Factorizamos $-5t^2+25t=-5t(t-5)=0$. Sirve $t=5$ s (el $t=0$ es el lanzamiento)."},{"q":"Dos números positivos suman 7 y su producto es 12. ¿Cuál es el mayor?","options":["6","3","4"],"correct":2,"why":"Con $x$ uno de ellos: $x(7-x)=12$, o sea $x^2-7x+12=0$, cuyas soluciones son 3 y 4."},{"type":"input","kind":"number","q":"Dos números positivos suman 15 y su producto es 54. ¿Cuál es el mayor?","answer":"9","why":"Con $x$ uno de ellos: $x(15-x)=54$, o sea $x^2-15x+54=0$, cuyas soluciones son 6 y 9."},{"q":"La altura de un triángulo mide $x$ cm y su base mide 5 cm más que la altura. Si el área es $63\\,\\mathrm{cm}^2$, ¿cuánto mide la altura?","options":["$63\\,\\mathrm{cm}$","$9\\,\\mathrm{cm}$","$10\\,\\mathrm{cm}$","$14\\,\\mathrm{cm}$"],"correct":1,"why":"El área es $\\frac{x(x+5)}{2}=63$; luego $x^2+5x-126=0$ y $x=9$."},{"q":"La altura de un triángulo mide $x$ cm y su base mide 1 cm más que la altura. Si el área es $21\\,\\mathrm{cm}^2$, ¿cuánto mide la altura?","options":["$6\\,\\mathrm{cm}$","$21\\,\\mathrm{cm}$","$7\\,\\mathrm{cm}$"],"correct":0,"why":"El área es $\\frac{x(x+1)}{2}=21$; luego $x^2+1x-42=0$ y $x=6$."}],"check":{"type":"input","kind":"number","q":"Un parche cuadrado de cultivo se amplía agregando 2 cm a cada lado, y el área final es de $64\\,\\mathrm{cm}^2$. Si $x$ es el lado original en cm, se cumple $(x + 2)^2 = 64$. ¿Cuánto medía el lado original? Escribe solo el número, en $\\mathrm{cm}$.","answer":"6","why":"El nuevo lado es $x + 2 = 8$, porque debe ser positivo; luego se resta lo agregado: $x = 6$."},"draw":5,"checks":[{"q":"La altura de una pelota lanzada hacia arriba es $h(t) = -5t^2 + 20t$. ¿En qué instante vuelve al suelo?","options":["$2\\,\\mathrm{s}$","$4\\,\\mathrm{s}$","$20\\,\\mathrm{s}$","$0\\,\\mathrm{s}$"],"correct":1,"why":"Resolvemos $-5t^2 + 20t = 0$: $-5t(t - 4) = 0$. Sirve $t = 4$ s."},{"type":"input","kind":"number","q":"Una piedra lanzada verticalmente sigue $h(t) = -5t^2 + 35t$ (en metros). ¿Cuántos segundos pasan hasta que vuelve al suelo? Escribe solo el número, en $\\mathrm{s}$.","answer":"7","why":"Resolvemos $-5t^2 + 35t = 0$: $-5t(t - 7) = 0$. Sirve $t = 7$ s."},{"q":"Un cohete de agua tiene altura $h(t) = -5t^2 + 25t$. ¿En cuántos segundos regresa al suelo?","options":["$5\\,\\mathrm{s}$","$25\\,\\mathrm{s}$","$\\dfrac{5}{2}\\,\\mathrm{s}$","$0\\,\\mathrm{s}$"],"correct":0,"why":"Resolvemos $-5t^2 + 25t = 0$: $-5t(t - 5) = 0$. Sirve $t = 5$ s."},{"type":"input","kind":"number","q":"Una carga se lanza desde una altura inicial y su altura es $h(t) = -5t^2 + 10t + 120$. ¿Cuántos segundos tarda en llegar al suelo? Escribe solo el número, en $\\mathrm{s}$.","answer":"6","why":"$-5t^2 + 10t + 120 = 0$ equivale a $t^2 - 2t - 24 = 0$, es decir $(t - 6)(t + 4) = 0$. Sirve $t = 6$."},{"q":"Un terreno rectangular de cultivo tiene un área de $60\\,\\mathrm{m^2}$ y su largo mide $4\\,\\mathrm{m}$ más que su ancho. ¿Cuánto mide el ancho?","options":["$5\\,\\mathrm{m}$","$10\\,\\mathrm{m}$","$30\\,\\mathrm{m}$","$6\\,\\mathrm{m}$"],"correct":3,"why":"Con ancho $x$: $x(x+4) = 60$; luego $x^2 + 4x - 60 = 0$ y $x = 6$."},{"type":"input","kind":"number","q":"Un acuario rectangular tiene una base de $252\\,\\mathrm{cm^2}$ y su largo mide $4\\,\\mathrm{cm}$ más que su ancho. ¿Cuánto mide el ancho en cm? Escribe solo el número, en $\\mathrm{m}$.","answer":"14","why":"Con ancho $x$: $x(x+4) = 252$; luego $x^2 + 4x - 252 = 0$ y $x = 14$."},{"q":"Una parcela experimental rectangular tiene $36\\,\\mathrm{m^2}$ de área y su largo excede en $5\\,\\mathrm{m}$ a su ancho. ¿Cuál es su ancho?","options":["$4\\,\\mathrm{m}$","$9\\,\\mathrm{m}$","$3\\,\\mathrm{m}$","$18\\,\\mathrm{m}$"],"correct":0,"why":"Con ancho $x$: $x(x+5) = 36$; luego $x^2 + 5x - 36 = 0$ y $x = 4$."},{"type":"input","kind":"number","q":"Una placa rectangular de un sensor tiene un área de $140\\,\\mathrm{mm^2}$ y su largo mide $4\\,\\mathrm{mm}$ más que su ancho. ¿Cuánto mide el ancho? Escribe solo el número, en $\\mathrm{m}$.","answer":"10","why":"Con ancho $x$: $x(x+4) = 140$; luego $x^2 + 4x - 140 = 0$ y $x = 10$."},{"q":"Un cable de $15\\,\\mathrm{m}$ une el suelo con lo alto de un poste. La base del cable está a $x$ metros del poste y el poste mide $(x + 3)$ metros. Por Pitágoras, $x^2 + (x+3)^2 = 15^2$. ¿Cuánto vale $x$?","options":["$9\\,\\mathrm{m}$","$12\\,\\mathrm{m}$","$\\dfrac{15}{2}\\,\\mathrm{m}$","$10\\,\\mathrm{m}$"],"correct":0,"why":"Por Pitágoras: $x^2 + (x+3)^2 = 15^2$. Esto da $2x^2 + 6x - 216 = 0$, cuya solución positiva es $x = 9$."},{"type":"input","kind":"number","q":"Una rampa de $29\\,\\mathrm{m}$ de largo sube hasta una plataforma. Su base horizontal mide $x$ m y la altura $(x + 1)$ m, así que $x^2 + (x+1)^2 = 29^2$. ¿Cuánto vale $x$? Escribe solo el número, en $\\mathrm{m}$.","answer":"20","why":"Por Pitágoras: $x^2 + (x+1)^2 = 29^2$. Esto da $2x^2 + 2x - 840 = 0$, cuya solución positiva es $x = 20$."},{"q":"Dos sondas parten de un mismo punto: una recorre $x$ km al este y otra $(x + 1)$ km al norte, quedando a $5$ km entre sí. Se cumple $x^2 + (x+1)^2 = 5^2$. ¿Cuánto vale $x$?","options":["$3\\,\\mathrm{m}$","$4\\,\\mathrm{m}$","$\\dfrac{5}{2}\\,\\mathrm{m}$"],"correct":0,"why":"Por Pitágoras: $x^2 + (x+1)^2 = 5^2$. Esto da $2x^2 + 2x - 24 = 0$, cuya solución positiva es $x = 3$."},{"type":"input","kind":"number","q":"Una antena de $10\\,\\mathrm{m}$ de cable se tensa; la distancia $x$ al pie y la altura $(x + 2)$ cumplen $x^2 + (x+2)^2 = 10^2$. ¿Cuánto vale $x$? Escribe solo el número, en $\\mathrm{m}$.","answer":"6","why":"Por Pitágoras: $x^2 + (x+2)^2 = 10^2$. Esto da $2x^2 + 4x - 96 = 0$, cuya solución positiva es $x = 6$."},{"q":"En un equilibrio químico, el producto de las concentraciones $x$ y $(x + 1)$ es $72$. ¿Cuánto vale la concentración positiva $x$?","options":["$-9$","$9$","$8$","$36$"],"correct":2,"why":"$x(x+1) = 72$ da $x^2 + 1x - 72 = 0$, es decir $(x + 9)(x - 8) = 0$. Como $x>0$, $x = 8$."},{"type":"input","kind":"number","q":"Dos gases tienen presiones $x$ y $(x + 1)$ y su producto es $30$. Si $x>0$, ¿cuánto vale $x$?","answer":"5","why":"$x(x+1) = 30$ da $x^2 + 1x - 30 = 0$, es decir $(x + 6)(x - 5) = 0$. Como $x>0$, $x = 5$."},{"q":"En una reacción, $x(x + 5) = 104$ con $x>0$ (concentración). ¿Cuánto vale $x$?","options":["$8$","$13$","$52$","$-13$"],"correct":0,"why":"$x(x+5) = 104$ da $x^2 + 5x - 104 = 0$, es decir $(x + 13)(x - 8) = 0$. Como $x>0$, $x = 8$."},{"q":"El crecimiento de una colonia cumple $t^2 + 2t = 48$, donde $t$ son los días transcurridos. ¿Cuántos días pasan?","options":["$6\\ \\text{días}$","$8\\ \\text{días}$","$-8\\ \\text{días}$","$16\\ \\text{días}$"],"correct":0,"why":"$t^2 + 2t = 48$ equivale a $t^2 + 2t - 48 = 0$, es decir $(t - 6)(t + 8) = 0$. Sirve $t = 6$."},{"q":"En un cultivo, el área ocupada (en $\\mathrm{cm^2}$) cumple $t^2 + 1t = 20$, con $t$ en días. ¿Cuántos días han pasado?","options":["$5\\ \\text{días}$","$10\\ \\text{días}$","$-5\\ \\text{días}$","$4\\ \\text{días}$"],"correct":3,"why":"$t^2 + 1t = 20$ equivale a $t^2 + 1t - 20 = 0$, es decir $(t - 4)(t + 5) = 0$. Sirve $t = 4$."},{"q":"Una lámina cuadrada de metal se calienta y cada lado se alarga $5\\,\\mathrm{cm}$, quedando con un área de $81\\,\\mathrm{cm^2}$. ¿Cuánto medía el lado original?","options":["$9\\,\\mathrm{cm}$","$4\\,\\mathrm{cm}$","$14\\,\\mathrm{cm}$","$20\\,\\mathrm{cm}$"],"correct":1,"why":"$(x+5)^2 = 81$ da $x + 5 = 9$, luego $x = 4$."},{"q":"Un cultivo cuadrado se amplía agregando $1\\,\\mathrm{cm}$ a cada lado y su área pasa a ser $64\\,\\mathrm{cm^2}$. ¿Cuánto medía el lado original?","options":["$8\\,\\mathrm{cm}$","$9\\,\\mathrm{cm}$","$16\\,\\mathrm{cm}$","$7\\,\\mathrm{cm}$"],"correct":3,"why":"$(x+1)^2 = 64$ da $x + 1 = 8$, luego $x = 7$."}],"drawCheck":5,"unit":0}];
